-- >>> 0001_extensions_and_enums.sql ===============================

-- =============================================================================
-- 0001  Extensions, schemas and enumerated types
-- =============================================================================
-- Every internal identifier in this system is a UUID (PRD 17). Human-facing
-- numbers (order number, daily KOT number) are generated separately in 0011.
-- =============================================================================

create extension if not exists "pgcrypto";      -- gen_random_uuid()

-- Email is stored as plain text with a lower() unique index rather than
-- citext, so the schema depends on no optional contrib module.

-- Internal helper schema: nothing in here is exposed through PostgREST.
create schema if not exists app;
revoke all on schema app from public, anon, authenticated;

-- -----------------------------------------------------------------------------
-- Roles (PRD 5). Role *quantities* are never hardcoded; this enumerates the
-- kinds of role that exist, not how many people hold them.
-- -----------------------------------------------------------------------------
create type public.app_role as enum (
  'developer_admin',
  'owner',
  'branch_manager',
  'kitchen_staff',
  'customer'
);

-- -----------------------------------------------------------------------------
-- Order sources (PRD 4). Prefixes: SW = Swiggy, ZM = Zomato, SX = subscription.
-- -----------------------------------------------------------------------------
create type public.order_source as enum ('SX', 'SW', 'ZM');

-- -----------------------------------------------------------------------------
-- KOT lifecycle (PRD 9).
--   NEW -> ACCEPTED -> PREPARING -> READY_FOR_PICKUP
--       -> PICKED_UP -> OUT_FOR_DELIVERY -> DELIVERED -> COMPLETED
-- REJECTED and CANCELLED are terminal side-exits, not part of the happy path.
-- -----------------------------------------------------------------------------
create type public.kot_status as enum (
  'NEW',
  'ACCEPTED',
  'PREPARING',
  'READY_FOR_PICKUP',
  'PICKED_UP',
  'OUT_FOR_DELIVERY',
  'DELIVERED',
  'COMPLETED',
  'REJECTED',
  'CANCELLED'
);

-- -----------------------------------------------------------------------------
-- Order state is kept deliberately separate from payment state and from KOT
-- state (PRD 8, PRD 20). An order can be CONFIRMED while its ticket is still
-- NEW, and a payment can be REFUNDED long after the order is COMPLETED.
-- -----------------------------------------------------------------------------
create type public.order_status as enum (
  'DRAFT',            -- built, not yet paid for / not yet ingested
  'AWAITING_PAYMENT', -- website order waiting on verified payment
  'CONFIRMED',        -- payment verified (or marketplace-accepted) -> KOT eligible
  'IN_PROGRESS',      -- ticket is moving through the kitchen
  'COMPLETED',
  'CANCELLED',
  'REJECTED'
);

create type public.payment_status as enum (
  'pending',
  'processing',
  'success',
  'failed',
  'refunded',
  'partially_refunded'
);

-- COD exists in the model but is paused (PRD 3, PRD 8). Enabling it is a
-- settings change, not a code change.
create type public.payment_provider as enum ('razorpay', 'cashfree', 'cod');

create type public.payment_flow as enum ('one_time', 'recurring');

create type public.subscription_status as enum (
  'pending_payment',  -- created but NOT active; creates no KOT
  'active',
  'paused',
  'past_due',         -- inside the configurable grace period
  'cancelled',
  'expired'
);

-- PRD 7: fixed meals, meal credits, scheduled meals, customer-selected meals.
create type public.plan_type as enum (
  'fixed_meals',
  'meal_credits',
  'scheduled_meals',
  'customer_selected'
);

create type public.subscription_delivery_status as enum (
  'scheduled',   -- generated from plan rules, not yet due
  'released',    -- inside the KOT release lead time; ticket created
  'skipped',     -- customer skipped; entitlement returned per settings
  'cancelled',
  'fulfilled'
);

-- The credit ledger is append-only (PRD 7: "a credit ledger, not only a
-- mutable balance"). Balance is always derived from these entries.
create type public.credit_entry_type as enum (
  'grant',      -- plan purchase / renewal granted credits
  'consume',    -- a delivery consumed credits
  'reverse',    -- a skip/cancellation returned credits
  'expire',
  'adjust'      -- manual owner correction, always audited
);

create type public.review_status as enum ('pending', 'published', 'hidden', 'rejected');

create type public.coupon_discount_type as enum ('percent', 'fixed_amount');

create type public.notification_channel as enum ('whatsapp', 'sms', 'email');

create type public.notification_status as enum ('queued', 'sending', 'sent', 'failed', 'dead_letter');

create type public.integration_provider as enum ('swiggy', 'zomato');

-- Integration capability state (PRD 16 / PRD 23): every marketplace feature is
-- explicitly labelled so the UI never implies more than the API really offers.
create type public.integration_capability_state as enum ('integrated', 'mocked', 'blocked');

create type public.integration_health as enum ('connected', 'degraded', 'down', 'disabled');

create type public.audit_action as enum (
  'insert', 'update', 'delete', 'login', 'logout',
  'state_transition', 'permission_change', 'config_change'
);


-- >>> 0002_identity_rbac_audit.sql ================================

-- =============================================================================
-- 0002  Identity, RBAC and the audit trail
-- =============================================================================
-- Authorization is data, not code: which role may do what lives in
-- role_permissions, so permissions can be retuned without a deploy (PRD 20).
-- Every policy in 0090_rls.sql resolves through the helpers defined here.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Shared trigger helpers
-- -----------------------------------------------------------------------------
create or replace function app.touch_updated_at()
returns trigger
language plpgsql
as $fn$
begin
  new.updated_at := now();
  return new;
end;
$fn$;

-- -----------------------------------------------------------------------------
-- auth_profiles: one row per authenticated principal, keyed to Supabase auth.
-- Customers get a profile too, with role = 'customer'.
-- -----------------------------------------------------------------------------
create table public.auth_profiles (
  id              uuid primary key references auth.users(id) on delete cascade,
  full_name       text        not null default '',
  email           text,
  phone           text,
  phone_verified  boolean     not null default false,
  role            public.app_role not null default 'customer',
  is_active       boolean     not null default true,
  -- Account deletion disables login but preserves historical business records
  -- (PRD 14). We never hard-delete a profile that has orders against it.
  disabled_at     timestamptz,
  disabled_reason text,
  last_login_at   timestamptz,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

create index auth_profiles_role_idx on public.auth_profiles(role) where is_active;
create unique index auth_profiles_email_key on public.auth_profiles(lower(email)) where email is not null;

create trigger auth_profiles_touch
  before update on public.auth_profiles
  for each row execute function app.touch_updated_at();

-- -----------------------------------------------------------------------------
-- Permission catalogue. Codes are '<domain>.<action>' and are referenced by
-- both RLS policies and the server-side API guard.
-- -----------------------------------------------------------------------------
create table public.permissions (
  code        text primary key,
  domain      text not null,
  description text not null default '',
  created_at  timestamptz not null default now()
);

create table public.role_permissions (
  role            public.app_role not null,
  permission_code text not null references public.permissions(code) on delete cascade,
  granted_at      timestamptz not null default now(),
  primary key (role, permission_code)
);

create index role_permissions_role_idx on public.role_permissions(role);

-- -----------------------------------------------------------------------------
-- employees: staffing records. Counts are configurable data, never constants
-- (PRD 5) -- add a fourth kitchen hand by inserting a row.
-- -----------------------------------------------------------------------------
create table public.employees (
  id            uuid primary key default gen_random_uuid(),
  profile_id    uuid not null unique references public.auth_profiles(id) on delete cascade,
  employee_code text not null unique,
  display_name  text not null,
  role          public.app_role not null,
  hired_on      date,
  is_active     boolean not null default true,
  notes         text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint employees_role_is_staff
    check (role in ('developer_admin', 'owner', 'branch_manager', 'kitchen_staff'))
);

create trigger employees_touch
  before update on public.employees
  for each row execute function app.touch_updated_at();

-- =============================================================================
-- Authorization helpers
-- =============================================================================
-- These are SECURITY DEFINER so that reading a caller's own role from inside an
-- RLS policy does not itself re-enter RLS on auth_profiles (infinite recursion).
-- search_path is pinned to defeat search-path hijacking.
-- =============================================================================

-- Server-side jobs (webhooks, schedulers, seeds) run as the service role with
-- no JWT. They announce who they are acting for via a session GUC so the audit
-- trail still names a real actor instead of "system".
create or replace function app.current_actor_id()
returns uuid
language sql
stable
security definer
set search_path = ''
as $fn$
  select coalesce(
    nullif(current_setting('app.actor_id', true), '')::uuid,
    auth.uid()
  );
$fn$;

create or replace function app.current_role()
returns public.app_role
language sql
stable
security definer
set search_path = ''
as $fn$
  select p.role
  from public.auth_profiles p
  where p.id = app.current_actor_id()
    and p.is_active;
$fn$;

-- The service role bypasses RLS anyway; this makes the intent explicit in
-- policies that also need to admit trusted server code.
create or replace function app.is_service_role()
returns boolean
language sql
stable
as $fn$
  select coalesce(
    current_setting('request.jwt.claims', true)::jsonb ->> 'role', ''
  ) = 'service_role';
$fn$;

-- True when there is no PostgREST request context at all -- a migration, the
-- seed, or a psql session. Such a connection is already fully trusted (it can
-- ALTER TABLE), so the privilege guards below exempt it rather than blocking
-- the bootstrap that grants the very first administrator their role.
create or replace function app.is_direct_connection()
returns boolean
language sql
stable
as $fn$
  select nullif(current_setting('request.jwt.claims', true), '') is null;
$fn$;

create or replace function app.has_permission(p_code text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $fn$
  select app.is_service_role()
      or exists (
        select 1
        from public.role_permissions rp
        where rp.role = app.current_role()
          and rp.permission_code = p_code
      );
$fn$;

create or replace function app.has_any_permission(p_codes text[])
returns boolean
language sql
stable
security definer
set search_path = ''
as $fn$
  select app.is_service_role()
      or exists (
        select 1
        from public.role_permissions rp
        where rp.role = app.current_role()
          and rp.permission_code = any(p_codes)
      );
$fn$;

create or replace function app.is_staff()
returns boolean
language sql
stable
security definer
set search_path = ''
as $fn$
  select app.current_role() in
    ('developer_admin', 'owner', 'branch_manager', 'kitchen_staff');
$fn$;

-- Owner and Developer Admin are the only audit-log readers (PRD 17).
create or replace function app.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $fn$
  select app.current_role() in ('developer_admin', 'owner');
$fn$;

grant usage on schema app to authenticated, anon, service_role;
grant execute on all functions in schema app to authenticated, anon, service_role;

-- =============================================================================
-- Audit log (PRD 17)
-- =============================================================================
create table public.audit_logs (
  id           bigserial primary key,
  occurred_at  timestamptz not null default now(),
  actor_id     uuid references public.auth_profiles(id) on delete set null,
  actor_role   public.app_role,
  actor_label  text,                    -- survives actor deletion
  action       public.audit_action not null,
  entity_type  text not null,
  entity_id    text,
  old_values   jsonb,
  new_values   jsonb,
  changed_keys text[],
  context      jsonb not null default '{}'::jsonb,
  request_id   text,
  ip_address   inet,
  user_agent   text
);

create index audit_logs_entity_idx    on public.audit_logs(entity_type, entity_id, occurred_at desc);
create index audit_logs_actor_idx     on public.audit_logs(actor_id, occurred_at desc);
create index audit_logs_occurred_idx  on public.audit_logs(occurred_at desc);

-- Append-only: nobody, including Owner, may rewrite history.
--
-- A trigger rather than a RULE: rules would silently discard the write (so a
-- caller would believe it succeeded), and any table carrying a rule cannot be
-- the target of INSERT ... ON CONFLICT, which the ledger in 0006 depends on.
create or replace function app.forbid_mutation()
returns trigger
language plpgsql
as $fn$
begin
  raise exception '% is append-only; % is not permitted', tg_table_name, tg_op
    using errcode = 'insufficient_privilege';
end;
$fn$;

create trigger audit_logs_append_only
  before update or delete on public.audit_logs
  for each row execute function app.forbid_mutation();

-- -----------------------------------------------------------------------------
-- Generic audit trigger. Attach to any table whose changes must be traceable;
-- records only the keys that actually changed so the log stays readable.
-- Pass a Postgres array literal of column names to redact, e.g.
--   execute function app.audit_trigger('{credentials,webhook_secret}')
-- -----------------------------------------------------------------------------
create or replace function app.audit_trigger()
returns trigger
language plpgsql
security definer
set search_path = ''
as $fn$
declare
  v_old       jsonb;
  v_new       jsonb;
  v_changed   text[];
  v_action    public.audit_action;
  v_entity_id text;
  v_actor     uuid := app.current_actor_id();
  v_redact    text[] := case when tg_nargs > 0 then tg_argv[0]::text[] else '{}'::text[] end;
  v_key       text;
begin
  if tg_op = 'INSERT' then
    v_action := 'insert';
    v_new := to_jsonb(new);
  elsif tg_op = 'UPDATE' then
    v_action := 'update';
    v_old := to_jsonb(old);
    v_new := to_jsonb(new);
  else
    v_action := 'delete';
    v_old := to_jsonb(old);
  end if;

  -- Never let secrets or PII the log does not need reach the audit trail.
  foreach v_key in array v_redact loop
    if v_old ? v_key then v_old := jsonb_set(v_old, array[v_key], to_jsonb('[redacted]'::text)); end if;
    if v_new ? v_key then v_new := jsonb_set(v_new, array[v_key], to_jsonb('[redacted]'::text)); end if;
  end loop;

  if tg_op = 'UPDATE' then
    select array_agg(n.key)
      into v_changed
      from jsonb_each(v_new) as n(key, value)
     where v_old -> n.key is distinct from n.value
       and n.key <> 'updated_at';

    -- A no-op update is not worth a row.
    if v_changed is null then
      return new;
    end if;
  end if;

  -- Join tables have no surrogate id; fall back to the owning entity so the
  -- log entry still points somewhere useful.
  v_entity_id := coalesce(
    v_new ->> 'id',         v_old ->> 'id',
    v_new ->> 'product_id', v_old ->> 'product_id',
    v_new ->> 'key',        v_old ->> 'key'
  );

  insert into public.audit_logs
    (actor_id, actor_role, actor_label, action, entity_type, entity_id,
     old_values, new_values, changed_keys, request_id)
  values
    (v_actor,
     app.current_role(),
     (select coalesce(nullif(p.full_name, ''), p.email, p.id::text)
        from public.auth_profiles p where p.id = v_actor),
     v_action,
     tg_table_name,
     v_entity_id,
     v_old,
     v_new,
     v_changed,
     nullif(current_setting('app.request_id', true), ''));

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$fn$;

-- Convenience wrapper for explicit, non-row-shaped audit events written by
-- application code (logins, config changes, state transitions).
create or replace function public.record_audit_event(
  p_action      public.audit_action,
  p_entity_type text,
  p_entity_id   text,
  p_old         jsonb default null,
  p_new         jsonb default null,
  p_context     jsonb default '{}'::jsonb
)
returns bigint
language plpgsql
security definer
set search_path = ''
as $fn$
declare
  v_id    bigint;
  v_actor uuid := app.current_actor_id();
begin
  insert into public.audit_logs
    (actor_id, actor_role, actor_label, action, entity_type, entity_id,
     old_values, new_values, context, request_id)
  values
    (v_actor,
     app.current_role(),
     (select coalesce(nullif(p.full_name, ''), p.email, p.id::text)
        from public.auth_profiles p where p.id = v_actor),
     p_action, p_entity_type, p_entity_id, p_old, p_new, p_context,
     nullif(current_setting('app.request_id', true), ''))
  returning id into v_id;

  return v_id;
end;
$fn$;

create trigger auth_profiles_audit
  after insert or update or delete on public.auth_profiles
  for each row execute function app.audit_trigger();

create trigger employees_audit
  after insert or update or delete on public.employees
  for each row execute function app.audit_trigger();

create trigger role_permissions_audit
  after insert or update or delete on public.role_permissions
  for each row execute function app.audit_trigger();


-- >>> 0003_business_settings.sql ==================================

-- =============================================================================
-- 0003  Configurable business settings (PRD 6, 7, 10, 12, 20)
-- =============================================================================
-- Nothing business-critical is a constant in application code. Fees, taxes,
-- delivery windows, grace periods, pause/skip rules, the KOT release lead time
-- and every cost assumption live here and are read at request time.
--
-- Money is stored as numeric(12,2) in rupees. Payment adapters convert to the
-- gateway's minor units at the boundary; nothing else needs to know about paise.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- business_settings: typed key/value store for scalar business rules.
-- -----------------------------------------------------------------------------
create table public.business_settings (
  key           text primary key,
  value         jsonb       not null,
  value_type    text        not null check (value_type in ('string','number','integer','boolean','json')),
  group_name    text        not null default 'general',
  label         text        not null,
  description   text        not null default '',
  -- Settings a Branch Manager or Kitchen account must never read (PRD 17).
  is_sensitive  boolean     not null default false,
  -- Marks a value the owner still has to confirm (PRD 22). The UI surfaces
  -- these as "pending owner validation" rather than pretending they are policy.
  is_provisional boolean    not null default false,
  updated_by    uuid references public.auth_profiles(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create index business_settings_group_idx on public.business_settings(group_name);

create trigger business_settings_touch
  before update on public.business_settings
  for each row execute function app.touch_updated_at();

create trigger business_settings_audit
  after insert or update or delete on public.business_settings
  for each row execute function app.audit_trigger();

-- -----------------------------------------------------------------------------
-- Typed accessors. Application code and SQL both read settings through these,
-- so a missing key fails loudly instead of silently defaulting to zero.
-- -----------------------------------------------------------------------------
create or replace function app.setting(p_key text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $fn$
  select s.value from public.business_settings s where s.key = p_key;
$fn$;

create or replace function app.setting_numeric(p_key text)
returns numeric
language plpgsql
stable
security definer
set search_path = ''
as $fn$
declare v jsonb := app.setting(p_key);
begin
  if v is null then
    raise exception 'business setting % is not configured', p_key
      using errcode = 'no_data_found';
  end if;
  return (v #>> '{}')::numeric;
end;
$fn$;

create or replace function app.setting_int(p_key text)
returns integer
language sql
stable
security definer
set search_path = ''
as $fn$
  select app.setting_numeric(p_key)::integer;
$fn$;

create or replace function app.setting_bool(p_key text)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $fn$
declare v jsonb := app.setting(p_key);
begin
  if v is null then
    raise exception 'business setting % is not configured', p_key
      using errcode = 'no_data_found';
  end if;
  return (v #>> '{}')::boolean;
end;
$fn$;

create or replace function app.setting_text(p_key text)
returns text
language plpgsql
stable
security definer
set search_path = ''
as $fn$
declare v jsonb := app.setting(p_key);
begin
  if v is null then
    raise exception 'business setting % is not configured', p_key
      using errcode = 'no_data_found';
  end if;
  return v #>> '{}';
end;
$fn$;

-- -----------------------------------------------------------------------------
-- Business clock. The branch operates on Asia/Kolkata (PRD 10) but the zone is
-- a setting, so a second branch in another zone would not need a code change.
-- -----------------------------------------------------------------------------
create or replace function app.business_timezone()
returns text
language sql
stable
security definer
set search_path = ''
as $fn$
  select coalesce(app.setting('business.timezone') #>> '{}', 'Asia/Kolkata');
$fn$;

create or replace function app.business_now()
returns timestamp
language sql
stable
security definer
set search_path = ''
as $fn$
  select (now() at time zone app.business_timezone());
$fn$;

-- The business day that a given instant belongs to. Daily KOT sequences reset
-- on this boundary (PRD 10), not on UTC midnight.
create or replace function app.business_date(p_at timestamptz default now())
returns date
language sql
stable
security definer
set search_path = ''
as $fn$
  select (p_at at time zone app.business_timezone())::date;
$fn$;

-- -----------------------------------------------------------------------------
-- delivery_settings: delivery fee rules. Row-per-rule so tiers ("free above
-- N") can be added without touching pricing code. Highest priority match wins.
-- -----------------------------------------------------------------------------
create table public.delivery_settings (
  id                       uuid primary key default gen_random_uuid(),
  name                     text not null,
  base_fee                 numeric(12,2) not null default 0 check (base_fee >= 0),
  -- Null means "never free on subtotal alone".
  free_above_subtotal      numeric(12,2) check (free_above_subtotal >= 0),
  -- Reserved for a future distance-based provider; unused in Phase 1.
  per_km_fee               numeric(12,2) check (per_km_fee >= 0),
  applies_to_source        public.order_source,   -- null = all sources
  priority                 integer not null default 0,
  effective_from           timestamptz not null default now(),
  effective_to             timestamptz,
  is_active                boolean not null default true,
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now(),
  constraint delivery_settings_window check (effective_to is null or effective_to > effective_from)
);

create index delivery_settings_lookup_idx
  on public.delivery_settings(is_active, priority desc, effective_from desc);

create trigger delivery_settings_touch
  before update on public.delivery_settings
  for each row execute function app.touch_updated_at();

create trigger delivery_settings_audit
  after insert or update or delete on public.delivery_settings
  for each row execute function app.audit_trigger();

-- -----------------------------------------------------------------------------
-- tax_settings: Phase 1 assumption is 5% food tax split CGST 2.5% + SGST 2.5%
-- (PRD 6). Stored as two rows so the real GST treatment, once validated, is a
-- data change. Nothing in code assumes two components or 5%.
-- -----------------------------------------------------------------------------
create table public.tax_settings (
  id             uuid primary key default gen_random_uuid(),
  code           text not null,                  -- CGST, SGST, IGST, ...
  label          text not null,
  rate_percent   numeric(6,3) not null check (rate_percent >= 0 and rate_percent <= 100),
  applies_to     text not null default 'food' check (applies_to in ('food','delivery','packaging','all')),
  is_inclusive   boolean not null default false,
  effective_from timestamptz not null default now(),
  effective_to   timestamptz,
  is_active      boolean not null default true,
  -- The PRD flags production GST treatment as unvalidated (PRD 3, PRD 22).
  is_provisional boolean not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  constraint tax_settings_window check (effective_to is null or effective_to > effective_from)
);

create index tax_settings_lookup_idx on public.tax_settings(is_active, applies_to, effective_from desc);

create trigger tax_settings_touch
  before update on public.tax_settings
  for each row execute function app.touch_updated_at();

create trigger tax_settings_audit
  after insert or update or delete on public.tax_settings
  for each row execute function app.audit_trigger();

-- -----------------------------------------------------------------------------
-- cost_settings: fee and cost assumptions behind estimated profit (PRD 12).
-- Initially dummy data, explicitly flagged as such, and replaceable without a
-- code change.
-- -----------------------------------------------------------------------------
create table public.cost_settings (
  id                          uuid primary key default gen_random_uuid(),
  source                      public.order_source,  -- null = applies to all channels
  label                       text not null,
  -- Marketplace commission on gross order value.
  commission_percent          numeric(6,3) not null default 0 check (commission_percent >= 0),
  -- Payment gateway take: percent + fixed, both provider-configurable.
  payment_fee_percent         numeric(6,3) not null default 0 check (payment_fee_percent >= 0),
  payment_fee_fixed           numeric(12,2) not null default 0 check (payment_fee_fixed >= 0),
  packaging_cost_per_order    numeric(12,2) not null default 0 check (packaging_cost_per_order >= 0),
  -- Fallback when a product has no explicit estimated_cost.
  default_food_cost_percent   numeric(6,3) not null default 0
    check (default_food_cost_percent >= 0 and default_food_cost_percent <= 100),
  effective_from              timestamptz not null default now(),
  effective_to                timestamptz,
  is_active                   boolean not null default true,
  is_dummy_data               boolean not null default true,
  created_at                  timestamptz not null default now(),
  updated_at                  timestamptz not null default now(),
  constraint cost_settings_window check (effective_to is null or effective_to > effective_from)
);

-- At most one open-ended active row per channel, and one for the "all
-- channels" fallback. NULLS NOT DISTINCT is what makes the fallback row
-- unique too -- without it, several null-source rows could coexist.
create unique index cost_settings_active_source_idx
  on public.cost_settings(source)
  nulls not distinct
  where is_active and effective_to is null;

create trigger cost_settings_touch
  before update on public.cost_settings
  for each row execute function app.touch_updated_at();

create trigger cost_settings_audit
  after insert or update or delete on public.cost_settings
  for each row execute function app.audit_trigger();

-- -----------------------------------------------------------------------------
-- delivery_windows: breakfast / lunch / dinner are configurable rows, not an
-- enum (PRD 7). Each window carries its own ordering cut-off.
-- -----------------------------------------------------------------------------
create table public.delivery_windows (
  id                    uuid primary key default gen_random_uuid(),
  code                  text not null unique,          -- BREAKFAST, LUNCH, DINNER, ...
  label                 text not null,
  starts_at             time not null,
  ends_at               time not null,
  -- How long before starts_at the kitchen stops accepting changes.
  cutoff_minutes_before integer not null default 0 check (cutoff_minutes_before >= 0),
  sort_order            integer not null default 0,
  is_active             boolean not null default true,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  constraint delivery_windows_span check (ends_at > starts_at)
);

create trigger delivery_windows_touch
  before update on public.delivery_windows
  for each row execute function app.touch_updated_at();

create trigger delivery_windows_audit
  after insert or update or delete on public.delivery_windows
  for each row execute function app.audit_trigger();

-- -----------------------------------------------------------------------------
-- Resolved-fee helpers. Pricing code calls these so a fee change is a row edit.
-- -----------------------------------------------------------------------------
create or replace function app.resolve_delivery_fee(
  p_subtotal numeric,
  p_source   public.order_source default 'SX',
  p_at       timestamptz default now()
)
returns numeric
language plpgsql
stable
security definer
set search_path = ''
as $fn$
declare
  r public.delivery_settings%rowtype;
begin
  select *
    into r
    from public.delivery_settings d
   where d.is_active
     and (d.applies_to_source is null or d.applies_to_source = p_source)
     and d.effective_from <= p_at
     and (d.effective_to is null or d.effective_to > p_at)
   order by (d.applies_to_source is not null) desc, d.priority desc, d.effective_from desc
   limit 1;

  if not found then
    return 0;
  end if;

  if r.free_above_subtotal is not null and p_subtotal >= r.free_above_subtotal then
    return 0;
  end if;

  return r.base_fee;
end;
$fn$;

-- Returns one row per active tax component so invoices can show the split
-- (CGST 2.5% / SGST 2.5%) rather than a single opaque "tax" line.
create or replace function app.resolve_tax_components(
  p_applies_to text default 'food',
  p_at         timestamptz default now()
)
returns table (code text, label text, rate_percent numeric)
language sql
stable
security definer
set search_path = ''
as $fn$
  select t.code, t.label, t.rate_percent
    from public.tax_settings t
   where t.is_active
     and t.applies_to in (p_applies_to, 'all')
     and t.effective_from <= p_at
     and (t.effective_to is null or t.effective_to > p_at)
   order by t.code;
$fn$;


-- >>> 0004_catalog.sql ============================================

-- =============================================================================
-- 0004  Catalog (PRD 13)
-- =============================================================================
-- Shopify-like: products, images, categories, collections, shared variant
-- groups, add-ons, availability and calories are all rows. No product name,
-- image, price or badge is ever written in application code.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- categories: the single taxonomy a product belongs to (Mains, Breads, ...).
-- -----------------------------------------------------------------------------
create table public.categories (
  id          uuid primary key default gen_random_uuid(),
  slug        text not null unique,
  name        text not null,
  description text not null default '',
  image_url   text,
  sort_order  integer not null default 0,
  is_active   boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- collections: merchandising groupings a product may belong to many of
-- ("High Protein", "Chef's Picks"). Drives the website browse experience.
-- -----------------------------------------------------------------------------
create table public.collections (
  id            uuid primary key default gen_random_uuid(),
  slug          text not null unique,
  name          text not null,
  description   text not null default '',
  image_url     text,
  sort_order    integer not null default 0,
  is_published  boolean not null default true,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- products
-- -----------------------------------------------------------------------------
create table public.products (
  id                       uuid primary key default gen_random_uuid(),
  slug                     text not null unique,
  name                     text not null,
  short_description        text not null default '',
  description              text not null default '',
  category_id              uuid references public.categories(id) on delete set null,
  base_price               numeric(12,2) not null check (base_price >= 0),

  -- Nutrition / dietary facts shown on the menu.
  calories                 integer check (calories >= 0),
  protein_grams            numeric(6,2) check (protein_grams >= 0),
  is_vegetarian            boolean not null default true,
  allergens                text[] not null default '{}',

  -- Subscription economics: a premium meal may cost more than one credit
  -- (PRD 7). Never assume 1 credit == 1 meal. Zero is valid too -- a side or a
  -- bread can ride along with a plan meal without consuming entitlement.
  credit_cost              integer not null default 1 check (credit_cost >= 0),

  -- Profit estimation input (PRD 12). Null falls back to the channel's
  -- default_food_cost_percent in cost_settings.
  estimated_cost           numeric(12,2) check (estimated_cost >= 0),

  -- Availability. Unavailable products render grayscale with a badge and
  -- cannot be selected (PRD 6, PRD 19) -- enforced server-side as well.
  is_available             boolean not null default true,
  unavailable_reason       text,
  available_from           timestamptz,
  available_until          timestamptz,

  -- Visibility is separate from availability: a hidden product disappears
  -- entirely, an unavailable one is shown but not orderable.
  is_published             boolean not null default true,
  -- Soft delete keeps historical order lines meaningful (PRD 17).
  archived_at              timestamptz,

  allows_special_instructions boolean not null default true,
  max_quantity_per_order   integer check (max_quantity_per_order is null or max_quantity_per_order > 0),
  sort_order               integer not null default 0,
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now()
);

create index products_category_idx  on public.products(category_id);
create index products_browse_idx    on public.products(is_published, sort_order)
  where archived_at is null;

-- A product is orderable only when published, available, not archived and
-- inside any configured availability window. Both the API and RLS use this,
-- so the "cannot be selected" rule is never only a frontend concern.
create or replace function app.product_is_orderable(
  p_product_id uuid,
  p_at         timestamptz default now()
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $fn$
  select exists (
    select 1 from public.products p
     where p.id = p_product_id
       and p.is_published
       and p.is_available
       and p.archived_at is null
       and (p.available_from  is null or p.available_from  <= p_at)
       and (p.available_until is null or p.available_until >  p_at)
  );
$fn$;

create table public.product_images (
  id          uuid primary key default gen_random_uuid(),
  product_id  uuid not null references public.products(id) on delete cascade,
  url         text not null,
  alt_text    text not null default '',
  sort_order  integer not null default 0,
  is_primary  boolean not null default false,
  created_at  timestamptz not null default now()
);

create index product_images_product_idx on public.product_images(product_id, sort_order);
create unique index product_images_one_primary_idx
  on public.product_images(product_id) where is_primary;

create table public.collection_products (
  collection_id uuid not null references public.collections(id) on delete cascade,
  product_id    uuid not null references public.products(id) on delete cascade,
  sort_order    integer not null default 0,
  primary key (collection_id, product_id)
);

-- -----------------------------------------------------------------------------
-- Variant groups are defined once and attached to many products, so "Portion"
-- does not have to be re-created per meal.
-- -----------------------------------------------------------------------------
create table public.variant_groups (
  id              uuid primary key default gen_random_uuid(),
  code            text not null unique,
  name            text not null,
  selection_type  text not null default 'single' check (selection_type in ('single','multiple')),
  is_required     boolean not null default true,
  min_selections  integer not null default 1 check (min_selections >= 0),
  -- Null = unbounded. Phase 1 leaves room for the quantity constraints the
  -- PRD anticipates (PRD 13) without inventing rules for them yet.
  max_selections  integer check (max_selections is null or max_selections >= 1),
  sort_order      integer not null default 0,
  is_active       boolean not null default true,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint variant_groups_selection_bounds
    check (max_selections is null or max_selections >= min_selections)
);

create table public.variants (
  id               uuid primary key default gen_random_uuid(),
  variant_group_id uuid not null references public.variant_groups(id) on delete cascade,
  code             text not null,
  name             text not null,
  price_delta      numeric(12,2) not null default 0,
  -- A larger portion can legitimately cost an extra credit.
  credit_delta     integer not null default 0,
  calorie_delta    integer not null default 0,
  is_default       boolean not null default false,
  is_available     boolean not null default true,
  sort_order       integer not null default 0,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (variant_group_id, code)
);

create index variants_group_idx on public.variants(variant_group_id, sort_order);

create table public.product_variant_groups (
  product_id       uuid not null references public.products(id) on delete cascade,
  variant_group_id uuid not null references public.variant_groups(id) on delete cascade,
  sort_order       integer not null default 0,
  -- A product may make a normally optional group required, or vice versa.
  is_required_override boolean,
  primary key (product_id, variant_group_id)
);

-- -----------------------------------------------------------------------------
-- Add-ons: priced extras attachable to products.
-- -----------------------------------------------------------------------------
create table public.add_ons (
  id             uuid primary key default gen_random_uuid(),
  code           text not null unique,
  name           text not null,
  description    text not null default '',
  price          numeric(12,2) not null default 0 check (price >= 0),
  credit_cost    integer not null default 0 check (credit_cost >= 0),
  calories       integer check (calories >= 0),
  estimated_cost numeric(12,2) check (estimated_cost >= 0),
  image_url      text,
  is_available   boolean not null default true,
  is_active      boolean not null default true,
  sort_order     integer not null default 0,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create table public.product_add_ons (
  product_id  uuid not null references public.products(id) on delete cascade,
  add_on_id   uuid not null references public.add_ons(id) on delete cascade,
  max_quantity integer not null default 1 check (max_quantity >= 1),
  sort_order  integer not null default 0,
  primary key (product_id, add_on_id)
);

-- -----------------------------------------------------------------------------
-- Timestamps + audit on everything an Owner can change (PRD 17).
-- -----------------------------------------------------------------------------
create trigger categories_touch      before update on public.categories      for each row execute function app.touch_updated_at();
create trigger collections_touch     before update on public.collections     for each row execute function app.touch_updated_at();
create trigger products_touch        before update on public.products        for each row execute function app.touch_updated_at();
create trigger variant_groups_touch  before update on public.variant_groups  for each row execute function app.touch_updated_at();
create trigger variants_touch        before update on public.variants        for each row execute function app.touch_updated_at();
create trigger add_ons_touch         before update on public.add_ons         for each row execute function app.touch_updated_at();

create trigger categories_audit          after insert or update or delete on public.categories          for each row execute function app.audit_trigger();
create trigger collections_audit         after insert or update or delete on public.collections         for each row execute function app.audit_trigger();
create trigger products_audit            after insert or update or delete on public.products            for each row execute function app.audit_trigger();
create trigger product_images_audit      after insert or update or delete on public.product_images      for each row execute function app.audit_trigger();
create trigger collection_products_audit after insert or update or delete on public.collection_products for each row execute function app.audit_trigger();
create trigger variant_groups_audit      after insert or update or delete on public.variant_groups      for each row execute function app.audit_trigger();
create trigger variants_audit            after insert or update or delete on public.variants            for each row execute function app.audit_trigger();
create trigger add_ons_audit             after insert or update or delete on public.add_ons             for each row execute function app.audit_trigger();


-- >>> 0005_customers.sql ==========================================

-- =============================================================================
-- 0005  Customers and addresses (PRD 6, PRD 14)
-- =============================================================================
-- Customers normally arrive through a website order, but the Owner can create
-- one by hand for edge cases -- so profile_id is nullable and a customer can
-- exist without a login.
-- =============================================================================

create table public.customers (
  id             uuid primary key default gen_random_uuid(),
  -- Null for Owner-created records that have never signed in.
  profile_id     uuid unique references public.auth_profiles(id) on delete set null,
  full_name      text not null,
  email          text,
  phone          text not null,
  phone_verified boolean not null default false,

  -- Marketing consent is deliberately independent of account status (PRD 14):
  -- deleting an account must not be read as permission to keep marketing, and
  -- withdrawing marketing consent must not disable the account.
  marketing_consent            boolean not null default false,
  marketing_consent_updated_at timestamptz,
  marketing_consent_source     text,

  created_source text not null default 'website'
    check (created_source in ('website','owner','marketplace','import')),
  notes          text,

  -- Account deletion disables login while legitimate business records
  -- (orders, invoices, payments) are preserved (PRD 14). This is never a
  -- hard delete.
  is_active      boolean not null default true,
  deleted_at     timestamptz,
  deletion_reason text,

  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create unique index customers_phone_key on public.customers(phone) where deleted_at is null;
create unique index customers_email_key on public.customers(lower(email))
  where email is not null and deleted_at is null;
create index customers_profile_idx on public.customers(profile_id);

create table public.customer_addresses (
  id                   uuid primary key default gen_random_uuid(),
  customer_id          uuid not null references public.customers(id) on delete cascade,
  label                text not null default 'Home',
  recipient_name       text not null,
  phone                text not null,
  line1                text not null,
  line2                text,
  landmark             text,
  city                 text not null,
  state                text not null,
  postal_code          text not null,
  country              text not null default 'IN',
  latitude             numeric(9,6),
  longitude            numeric(9,6),
  -- Free-text notes for the rider/kitchen (PRD 6).
  delivery_instructions text,
  is_default           boolean not null default false,
  is_active            boolean not null default true,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

create index customer_addresses_customer_idx on public.customer_addresses(customer_id)
  where is_active;
create unique index customer_addresses_one_default_idx
  on public.customer_addresses(customer_id) where is_default and is_active;

-- Resolve the caller's own customer row. Customer-facing RLS policies compare
-- against this rather than trusting any client-supplied customer_id.
create or replace function app.current_customer_id()
returns uuid
language sql
stable
security definer
set search_path = ''
as $fn$
  select c.id
    from public.customers c
   where c.profile_id = app.current_actor_id()
     and c.deleted_at is null;
$fn$;

create trigger customers_touch          before update on public.customers          for each row execute function app.touch_updated_at();
create trigger customer_addresses_touch before update on public.customer_addresses for each row execute function app.touch_updated_at();

-- Customer records carry PII; the audit trail keeps the change history but
-- redacts contact details it does not need to prove who changed what.
create trigger customers_audit
  after insert or update or delete on public.customers
  for each row execute function app.audit_trigger('{email,phone}');

create trigger customer_addresses_audit
  after insert or update or delete on public.customer_addresses
  for each row execute function app.audit_trigger('{phone,line1,line2,landmark,latitude,longitude}');


-- >>> 0006_subscriptions.sql ======================================

-- =============================================================================
-- 0006  Subscription plans, subscriptions, credit ledger and deliveries
--       (PRD 7)
-- =============================================================================
-- The Owner creates real commercial plans; customers buy published, active
-- ones. Four plan shapes are supported and none of them is privileged in code:
-- fixed meals, meal credits, scheduled meals and customer-selected meals.
-- =============================================================================

create table public.subscription_plans (
  id                uuid primary key default gen_random_uuid(),
  slug              text not null unique,
  name              text not null,
  tagline           text not null default '',
  description       text not null default '',
  image_url         text,
  plan_type         public.plan_type not null,

  price             numeric(12,2) not null check (price >= 0),
  -- 'one_time' plans expire at the end of their cycle; 'recurring' plans renew
  -- until cancelled (PRD 7).
  payment_flow      public.payment_flow not null default 'one_time',
  billing_period_days integer not null check (billing_period_days > 0),

  -- Entitlement, interpreted per plan_type:
  --   fixed_meals / scheduled_meals / customer_selected -> meals_per_cycle
  --   meal_credits                                      -> credits_per_cycle
  meals_per_cycle   integer check (meals_per_cycle is null or meals_per_cycle > 0),
  credits_per_cycle integer check (credits_per_cycle is null or credits_per_cycle > 0),

  -- How many distinct meals a customer_selected plan lets the customer pick.
  selectable_meal_count integer check (selectable_meal_count is null or selectable_meal_count > 0),

  allows_variants   boolean not null default true,
  allows_add_ons    boolean not null default true,
  -- Per-delivery address override exists in the model but is gated on business
  -- approval (PRD 7, PRD 22); default off until the Owner confirms.
  allows_address_override boolean not null default false,

  -- Plan-level overrides of the global rules in business_settings. Null means
  -- "use the global setting" -- so the default lives in exactly one place.
  grace_period_days      integer check (grace_period_days is null or grace_period_days >= 0),
  max_pauses_per_period  integer check (max_pauses_per_period is null or max_pauses_per_period >= 0),
  max_pause_days         integer check (max_pause_days is null or max_pause_days >= 0),
  skip_returns_credit    boolean,

  is_published      boolean not null default false,
  is_active         boolean not null default true,
  archived_at       timestamptz,
  sort_order        integer not null default 0,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),

  -- Each plan shape must carry the entitlement it is meaningless without.
  constraint subscription_plans_entitlement check (
    (plan_type = 'meal_credits' and credits_per_cycle is not null)
    or (plan_type <> 'meal_credits' and meals_per_cycle is not null)
  )
);

create index subscription_plans_public_idx on public.subscription_plans(is_published, sort_order)
  where is_active and archived_at is null;

-- Which delivery windows a plan may be taken in.
create table public.subscription_plan_windows (
  plan_id           uuid not null references public.subscription_plans(id) on delete cascade,
  delivery_window_id uuid not null references public.delivery_windows(id) on delete restrict,
  primary key (plan_id, delivery_window_id)
);

-- -----------------------------------------------------------------------------
-- subscription_plan_meals: the plan's menu.
--   fixed_meals      -> the exact meals, optionally per weekday
--   scheduled_meals  -> meals bound to a day_of_week / window
--   customer_selected-> the pool the customer chooses from (is_selectable)
-- -----------------------------------------------------------------------------
create table public.subscription_plan_meals (
  id                 uuid primary key default gen_random_uuid(),
  plan_id            uuid not null references public.subscription_plans(id) on delete cascade,
  product_id         uuid not null references public.products(id) on delete restrict,
  -- 0 = Sunday .. 6 = Saturday, matching Postgres extract(dow). Null = any day.
  day_of_week        smallint check (day_of_week between 0 and 6),
  delivery_window_id uuid references public.delivery_windows(id) on delete set null,
  quantity           integer not null default 1 check (quantity > 0),
  -- True for the customer_selected pool; false for meals the plan fixes.
  is_selectable      boolean not null default false,
  sort_order         integer not null default 0,
  created_at         timestamptz not null default now()
);

create index subscription_plan_meals_plan_idx on public.subscription_plan_meals(plan_id, day_of_week);

-- =============================================================================
-- subscriptions
-- =============================================================================
create table public.subscriptions (
  id                    uuid primary key default gen_random_uuid(),
  subscription_number   text not null unique,
  customer_id           uuid not null references public.customers(id) on delete restrict,
  plan_id               uuid not null references public.subscription_plans(id) on delete restrict,

  -- A subscription is created pending_payment and only becomes active after
  -- server-side payment verification (PRD 7, PRD 8). Nothing downstream reads
  -- a pending subscription as an entitlement.
  status                public.subscription_status not null default 'pending_payment',

  -- Frozen copy of the plan's commercial terms at purchase time. Editing a
  -- plan later must never silently restate what an existing customer bought.
  plan_snapshot         jsonb not null,
  price_paid            numeric(12,2) not null check (price_paid >= 0),

  payment_flow          public.payment_flow not null default 'one_time',

  starts_on             date,
  ends_on               date,
  current_period_start  date,
  current_period_end    date,
  next_renewal_at       timestamptz,

  delivery_address_id   uuid references public.customer_addresses(id) on delete restrict,
  delivery_window_id    uuid references public.delivery_windows(id) on delete restrict,
  -- Weekdays this subscription delivers on; empty = every day.
  delivery_days         smallint[] not null default '{}',
  delivery_instructions text,

  -- Resolved at purchase from plan override or global setting, then frozen so
  -- a later settings change cannot retroactively expire someone.
  grace_period_days     integer not null,
  past_due_since        timestamptz,

  paused_until          date,
  pauses_used_this_period integer not null default 0,

  activated_at          timestamptz,
  cancelled_at          timestamptz,
  cancellation_reason   text,
  cancelled_by          uuid references public.auth_profiles(id) on delete set null,

  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),

  constraint subscriptions_active_needs_activation
    check (status <> 'active' or activated_at is not null),
  constraint subscriptions_period check (
    current_period_end is null or current_period_start is null
    or current_period_end >= current_period_start
  )
);

create index subscriptions_customer_idx on public.subscriptions(customer_id, status);
create index subscriptions_status_idx   on public.subscriptions(status)
  where status in ('active', 'paused', 'past_due');

-- -----------------------------------------------------------------------------
-- Customer-selected meals for a subscription (PRD 7).
-- -----------------------------------------------------------------------------
create table public.subscription_selected_meals (
  id                 uuid primary key default gen_random_uuid(),
  subscription_id    uuid not null references public.subscriptions(id) on delete cascade,
  product_id         uuid not null references public.products(id) on delete restrict,
  day_of_week        smallint check (day_of_week between 0 and 6),
  delivery_window_id uuid references public.delivery_windows(id) on delete set null,
  quantity           integer not null default 1 check (quantity > 0),
  created_at         timestamptz not null default now()
);

create index subscription_selected_meals_sub_idx on public.subscription_selected_meals(subscription_id);

-- =============================================================================
-- subscription_credit_ledger  (PRD 7: "a credit ledger, not only a mutable
-- balance")
-- =============================================================================
-- Append-only. The balance is always sum(credits); no row is ever updated, so
-- a reversal is a new compensating entry and the history stays truthful.
-- =============================================================================
create table public.subscription_credit_ledger (
  id              uuid primary key default gen_random_uuid(),
  subscription_id uuid not null references public.subscriptions(id) on delete cascade,
  entry_type      public.credit_entry_type not null,
  -- Signed: grants are positive, consumption negative, reversals positive.
  credits         integer not null,
  reason          text not null default '',
  delivery_id     uuid,          -- FK added in 0007 once deliveries exist
  -- Retrying a credit operation must not double-charge (PRD 7, PRD 11).
  idempotency_key text not null,
  created_by      uuid references public.auth_profiles(id) on delete set null,
  created_at      timestamptz not null default now(),

  constraint credit_ledger_sign check (
    (entry_type in ('grant','reverse') and credits > 0)
    or (entry_type in ('consume','expire') and credits < 0)
    or (entry_type = 'adjust')
  )
);

create unique index subscription_credit_ledger_idem_idx
  on public.subscription_credit_ledger(subscription_id, idempotency_key);
create index subscription_credit_ledger_sub_idx
  on public.subscription_credit_ledger(subscription_id, created_at);

-- Append-only, enforced by trigger. A correction is a new compensating entry,
-- never an edit to an existing one -- which is the whole point of a ledger.
create trigger subscription_credit_ledger_append_only
  before update or delete on public.subscription_credit_ledger
  for each row execute function app.forbid_mutation();

create or replace function public.subscription_credit_balance(p_subscription_id uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $fn$
  select coalesce(sum(l.credits), 0)::integer
    from public.subscription_credit_ledger l
   where l.subscription_id = p_subscription_id;
$fn$;

-- =============================================================================
-- subscription_deliveries: the schedule generated from plan rules. A delivery
-- becomes an operational order only when it is released to the KOT inside the
-- configurable lead time (PRD 7, PRD 9).
-- =============================================================================
create table public.subscription_deliveries (
  id                  uuid primary key default gen_random_uuid(),
  subscription_id     uuid not null references public.subscriptions(id) on delete cascade,
  customer_id         uuid not null references public.customers(id) on delete restrict,
  scheduled_date      date not null,
  delivery_window_id  uuid not null references public.delivery_windows(id) on delete restrict,
  status              public.subscription_delivery_status not null default 'scheduled',

  -- Per-delivery address override (PRD 7); null means use the subscription's
  -- address. Whether customers may set this is gated by the plan flag.
  address_id          uuid references public.customer_addresses(id) on delete restrict,
  delivery_instructions text,

  credits_cost        integer not null default 0 check (credits_cost >= 0),

  released_at         timestamptz,
  order_id            uuid,          -- FK added in 0007
  skipped_at          timestamptz,
  skip_reason         text,
  skipped_by          uuid references public.auth_profiles(id) on delete set null,
  cancelled_at        timestamptz,
  fulfilled_at        timestamptz,

  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),

  -- One delivery per subscription per date per window; the generator is
  -- idempotent because a re-run collides with this constraint (PRD 7).
  unique (subscription_id, scheduled_date, delivery_window_id)
);

create index subscription_deliveries_due_idx
  on public.subscription_deliveries(scheduled_date, status)
  where status = 'scheduled';
create index subscription_deliveries_sub_idx
  on public.subscription_deliveries(subscription_id, scheduled_date);
create index subscription_deliveries_customer_idx
  on public.subscription_deliveries(customer_id, scheduled_date desc);

create table public.subscription_delivery_items (
  id                 uuid primary key default gen_random_uuid(),
  delivery_id        uuid not null references public.subscription_deliveries(id) on delete cascade,
  product_id         uuid not null references public.products(id) on delete restrict,
  quantity           integer not null default 1 check (quantity > 0),
  -- Chosen variant ids; resolved to names/prices when the order is built.
  variant_ids        uuid[] not null default '{}',
  add_on_ids         uuid[] not null default '{}',
  credits_cost       integer not null default 0 check (credits_cost >= 0),
  special_instructions text,
  created_at         timestamptz not null default now()
);

create index subscription_delivery_items_delivery_idx
  on public.subscription_delivery_items(delivery_id);

-- -----------------------------------------------------------------------------
-- subscription_pauses: an explicit history rather than a mutable "paused"
-- flag, so pause quotas can be counted and audited (PRD 7).
-- -----------------------------------------------------------------------------
create table public.subscription_pauses (
  id              uuid primary key default gen_random_uuid(),
  subscription_id uuid not null references public.subscriptions(id) on delete cascade,
  starts_on       date not null,
  ends_on         date not null,
  reason          text,
  created_by      uuid references public.auth_profiles(id) on delete set null,
  cancelled_at    timestamptz,
  created_at      timestamptz not null default now(),
  constraint subscription_pauses_span check (ends_on >= starts_on)
);

create index subscription_pauses_sub_idx on public.subscription_pauses(subscription_id, starts_on desc);

create trigger subscription_plans_touch          before update on public.subscription_plans          for each row execute function app.touch_updated_at();
create trigger subscriptions_touch               before update on public.subscriptions               for each row execute function app.touch_updated_at();
create trigger subscription_deliveries_touch     before update on public.subscription_deliveries     for each row execute function app.touch_updated_at();

create trigger subscription_plans_audit      after insert or update or delete on public.subscription_plans      for each row execute function app.audit_trigger();
create trigger subscription_plan_meals_audit after insert or update or delete on public.subscription_plan_meals for each row execute function app.audit_trigger();
create trigger subscriptions_audit           after insert or update or delete on public.subscriptions           for each row execute function app.audit_trigger();
create trigger subscription_credit_ledger_audit after insert on public.subscription_credit_ledger              for each row execute function app.audit_trigger();
create trigger subscription_deliveries_audit after insert or update or delete on public.subscription_deliveries for each row execute function app.audit_trigger();
create trigger subscription_pauses_audit     after insert or update or delete on public.subscription_pauses     for each row execute function app.audit_trigger();


-- >>> 0007_orders_kot.sql =========================================

-- =============================================================================
-- 0007  Orders, KOT tickets, numbering and the server-side state machine
--       (PRD 8, 9, 10)
-- =============================================================================
-- Every channel converges on one internal KOT. Order state, payment state and
-- ticket state are three separate machines that never write each other's
-- columns.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Overall order number: a single sequence across all sources, 1..99,999,999
-- (PRD 10). Distinct from the daily, source-prefixed KOT number.
-- -----------------------------------------------------------------------------
create sequence public.order_number_seq
  as bigint start with 1 increment by 1 minvalue 1 maxvalue 99999999 no cycle;

create table public.orders (
  id                   uuid primary key default gen_random_uuid(),
  order_number         bigint not null unique default nextval('public.order_number_seq'),
  source               public.order_source not null,
  status               public.order_status not null default 'DRAFT',

  -- Marketplace orders may have no local customer record; website orders always do.
  customer_id          uuid references public.customers(id) on delete restrict,
  subscription_id      uuid references public.subscriptions(id) on delete restrict,
  subscription_delivery_id uuid references public.subscription_deliveries(id) on delete restrict,

  -- Marketplace identity kept alongside our own (PRD 16).
  external_order_id    text,
  external_status      text,
  external_payload     jsonb,

  placed_at            timestamptz not null default now(),
  business_date        date not null default app.business_date(),
  -- When the food is due. For subscriptions this comes from the delivery
  -- window; for marketplace orders it is "as soon as possible".
  scheduled_for        timestamptz,
  delivery_window_id   uuid references public.delivery_windows(id) on delete set null,

  -- Snapshots. A customer editing their address later must not rewrite what
  -- was delivered last month (PRD 17).
  customer_name_snapshot text,
  customer_phone_snapshot text,
  address_snapshot     jsonb,
  delivery_instructions text,
  special_instructions text,

  -- Money. All amounts in rupees; tax_breakdown keeps the CGST/SGST split.
  currency             text not null default 'INR',
  subtotal             numeric(12,2) not null default 0 check (subtotal >= 0),
  discount_total       numeric(12,2) not null default 0 check (discount_total >= 0),
  delivery_fee         numeric(12,2) not null default 0 check (delivery_fee >= 0),
  tax_total            numeric(12,2) not null default 0 check (tax_total >= 0),
  tax_breakdown        jsonb not null default '[]'::jsonb,
  grand_total          numeric(12,2) not null default 0 check (grand_total >= 0),

  coupon_id            uuid,   -- FK added in 0009
  coupon_code          text,

  -- Analytics inputs, resolved from cost_settings at completion (PRD 12).
  estimated_food_cost  numeric(12,2),
  channel_fee_total    numeric(12,2),

  -- Retrying a checkout or replaying a marketplace webhook must not create a
  -- second order (PRD 8, PRD 11).
  idempotency_key      text,

  confirmed_at         timestamptz,
  completed_at         timestamptz,
  cancelled_at         timestamptz,
  cancellation_reason  text,

  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),

  -- A subscription order exists only against a real subscription delivery.
  constraint orders_subscription_shape check (
    source <> 'SX' or (subscription_id is not null and subscription_delivery_id is not null)
  ),
  constraint orders_marketplace_shape check (
    source = 'SX' or external_order_id is not null
  )
);

-- One internal order per marketplace order id, per marketplace. This is what
-- makes duplicate webhook delivery harmless.
create unique index orders_external_idx
  on public.orders(source, external_order_id) where external_order_id is not null;
create unique index orders_idempotency_idx
  on public.orders(idempotency_key) where idempotency_key is not null;
create index orders_business_date_idx on public.orders(business_date, source);
create index orders_customer_idx      on public.orders(customer_id, placed_at desc);
create index orders_status_idx        on public.orders(status) where status in ('CONFIRMED','IN_PROGRESS');

-- Close the circular references left open in 0006.
alter table public.subscription_deliveries
  add constraint subscription_deliveries_order_fk
  foreign key (order_id) references public.orders(id) on delete set null;

alter table public.subscription_credit_ledger
  add constraint subscription_credit_ledger_delivery_fk
  foreign key (delivery_id) references public.subscription_deliveries(id) on delete set null;

create table public.order_items (
  id                   uuid primary key default gen_random_uuid(),
  order_id             uuid not null references public.orders(id) on delete cascade,
  product_id           uuid references public.products(id) on delete set null,

  -- Name and price are snapshotted: renaming or repricing a product must not
  -- alter a historical ticket or invoice.
  name_snapshot        text not null,
  quantity             integer not null check (quantity > 0),
  unit_price           numeric(12,2) not null check (unit_price >= 0),
  line_subtotal        numeric(12,2) not null check (line_subtotal >= 0),

  -- [{group, name, price_delta}, ...] resolved at order time.
  variants_snapshot    jsonb not null default '[]'::jsonb,
  add_ons_snapshot     jsonb not null default '[]'::jsonb,

  credits_consumed     integer not null default 0 check (credits_consumed >= 0),
  estimated_cost       numeric(12,2),
  special_instructions text,
  created_at           timestamptz not null default now()
);

create index order_items_order_idx on public.order_items(order_id);

create table public.order_status_events (
  id          uuid primary key default gen_random_uuid(),
  order_id    uuid not null references public.orders(id) on delete cascade,
  from_status public.order_status,
  to_status   public.order_status not null,
  actor_id    uuid references public.auth_profiles(id) on delete set null,
  actor_role  public.app_role,
  reason      text,
  context     jsonb not null default '{}'::jsonb,
  occurred_at timestamptz not null default now()
);

create index order_status_events_order_idx on public.order_status_events(order_id, occurred_at);

-- =============================================================================
-- Daily, source-prefixed KOT numbering (PRD 9, PRD 10)
-- =============================================================================
-- SW-001 / ZM-001 / SX-001, reset every business day. The counter row is
-- locked per (business_date, source) so concurrent inserts cannot collide.
-- =============================================================================
create table public.kot_daily_counters (
  business_date date not null,
  source        public.order_source not null,
  last_number   integer not null default 0,
  primary key (business_date, source)
);

create or replace function app.next_kot_daily_number(
  p_source public.order_source,
  p_date   date
)
returns integer
language plpgsql
security definer
set search_path = ''
as $fn$
declare
  v_next integer;
begin
  insert into public.kot_daily_counters (business_date, source, last_number)
  values (p_date, p_source, 1)
  on conflict (business_date, source)
    do update set last_number = public.kot_daily_counters.last_number + 1
  returning last_number into v_next;

  return v_next;
end;
$fn$;

-- =============================================================================
-- kot_tickets
-- =============================================================================
create table public.kot_tickets (
  id             uuid primary key default gen_random_uuid(),
  order_id       uuid not null unique references public.orders(id) on delete cascade,
  source         public.order_source not null,
  business_date  date not null,
  daily_number   integer not null,
  -- Denormalised display code (SW-001). Colour is never the only signal --
  -- the prefix is always rendered too (PRD 19).
  ticket_code    text not null,

  status         public.kot_status not null default 'NEW',

  -- Higher runs first. Marketplace orders start above subscription deliveries
  -- because they are immediate (PRD 9); SLA pressure can escalate anything.
  priority       integer not null default 0,
  sla_due_at     timestamptz,

  -- Manager may override the kitchen's ETA (PRD 9); the original estimate is
  -- kept so the override is visible rather than silent.
  prep_eta_minutes          integer check (prep_eta_minutes is null or prep_eta_minutes > 0),
  prep_eta_minutes_original integer,
  eta_overridden_by         uuid references public.auth_profiles(id) on delete set null,
  eta_overridden_at         timestamptz,

  -- Lifecycle timestamps. prep time = accepted -> ready (PRD 10).
  accepted_at       timestamptz,
  accepted_by       uuid references public.auth_profiles(id) on delete set null,
  preparing_at      timestamptz,
  preparing_by      uuid references public.auth_profiles(id) on delete set null,
  ready_at          timestamptz,
  ready_by          uuid references public.auth_profiles(id) on delete set null,
  picked_up_at      timestamptz,
  out_for_delivery_at timestamptz,
  delivered_at      timestamptz,
  completed_at      timestamptz,
  rejected_at       timestamptz,
  rejected_by       uuid references public.auth_profiles(id) on delete set null,
  rejection_reason  text,
  cancelled_at      timestamptz,
  cancellation_reason text,
  cancellation_origin text check (cancellation_origin in ('internal','marketplace','customer')),

  notes          text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),

  unique (business_date, source, daily_number),
  -- Rejection must always carry a reason; the UI confirms it (PRD 9).
  constraint kot_tickets_rejection_reason
    check (status <> 'REJECTED' or rejection_reason is not null)
);

create index kot_tickets_board_idx
  on public.kot_tickets(status, priority desc, created_at)
  where status not in ('COMPLETED','REJECTED','CANCELLED');
create index kot_tickets_date_idx on public.kot_tickets(business_date, source);

create table public.kot_status_events (
  id          uuid primary key default gen_random_uuid(),
  ticket_id   uuid not null references public.kot_tickets(id) on delete cascade,
  from_status public.kot_status,
  to_status   public.kot_status not null,
  actor_id    uuid references public.auth_profiles(id) on delete set null,
  actor_role  public.app_role,
  notes       text,
  context     jsonb not null default '{}'::jsonb,
  occurred_at timestamptz not null default now()
);

create index kot_status_events_ticket_idx on public.kot_status_events(ticket_id, occurred_at);

-- =============================================================================
-- The KOT state machine, as data
-- =============================================================================
-- Which transitions exist, and which permission each one needs, are rows. That
-- is what makes "Owner KOT is read-only" and "Kitchen may start preparing but
-- not mark ready" enforceable server-side without a code branch per role.
-- =============================================================================
create table public.kot_transitions (
  from_status          public.kot_status not null,
  to_status            public.kot_status not null,
  required_permission  text not null references public.permissions(code) on delete restrict,
  requires_reason      boolean not null default false,
  requires_confirmation boolean not null default false,
  label                text not null,
  sort_order           integer not null default 0,
  primary key (from_status, to_status)
);

create or replace function app.kot_transition(
  p_from public.kot_status,
  p_to   public.kot_status
)
returns public.kot_transitions
language sql
stable
security definer
set search_path = ''
as $fn$
  select t.* from public.kot_transitions t
   where t.from_status = p_from and t.to_status = p_to;
$fn$;

-- -----------------------------------------------------------------------------
-- Enforcement trigger. Rejects illegal transitions and unauthorised actors,
-- stamps the matching timestamp, and records the event -- so history cannot be
-- skipped by a client that forgets to write it.
-- -----------------------------------------------------------------------------
create or replace function app.kot_enforce_transition()
returns trigger
language plpgsql
security definer
set search_path = ''
as $fn$
declare
  v_rule  public.kot_transitions%rowtype;
  v_actor uuid := app.current_actor_id();
  v_role  public.app_role := app.current_role();
begin
  if new.status = old.status then
    return new;
  end if;

  select * into v_rule
    from public.kot_transitions t
   where t.from_status = old.status and t.to_status = new.status;

  if not found then
    raise exception 'illegal KOT transition % -> % for ticket %',
      old.status, new.status, old.ticket_code
      using errcode = 'check_violation';
  end if;

  -- Service-role callers are trusted server code that has already run its own
  -- permission check; everyone else must actually hold the permission.
  if not app.has_permission(v_rule.required_permission) then
    raise exception 'role % may not perform transition % -> %',
      coalesce(v_role::text, 'anonymous'), old.status, new.status
      using errcode = 'insufficient_privilege';
  end if;

  if v_rule.requires_reason
     and coalesce(nullif(new.rejection_reason, ''), nullif(new.cancellation_reason, '')) is null then
    raise exception 'transition % -> % requires a reason', old.status, new.status
      using errcode = 'check_violation';
  end if;

  -- Stamp the lifecycle timestamp for the state being entered.
  case new.status
    when 'ACCEPTED'         then new.accepted_at := now();  new.accepted_by := v_actor;
    when 'PREPARING'        then new.preparing_at := now(); new.preparing_by := v_actor;
    when 'READY_FOR_PICKUP' then new.ready_at := now();     new.ready_by := v_actor;
    when 'PICKED_UP'        then new.picked_up_at := now();
    when 'OUT_FOR_DELIVERY' then new.out_for_delivery_at := now();
    when 'DELIVERED'        then new.delivered_at := now();
    when 'COMPLETED'        then new.completed_at := now();
    when 'REJECTED'         then new.rejected_at := now();  new.rejected_by := v_actor;
    when 'CANCELLED'        then new.cancelled_at := now();
    else null;
  end case;

  insert into public.kot_status_events (ticket_id, from_status, to_status, actor_id, actor_role, notes)
  values (new.id, old.status, new.status, v_actor, v_role,
          coalesce(new.rejection_reason, new.cancellation_reason));

  return new;
end;
$fn$;

create trigger kot_tickets_enforce_transition
  before update of status on public.kot_tickets
  for each row execute function app.kot_enforce_transition();

-- Record the ticket's birth as an event too, so the history has no gap.
create or replace function app.kot_record_creation()
returns trigger
language plpgsql
security definer
set search_path = ''
as $fn$
begin
  insert into public.kot_status_events (ticket_id, from_status, to_status, actor_id, actor_role)
  values (new.id, null, new.status, app.current_actor_id(), app.current_role());
  return new;
end;
$fn$;

create trigger kot_tickets_record_creation
  after insert on public.kot_tickets
  for each row execute function app.kot_record_creation();

-- -----------------------------------------------------------------------------
-- Order state machine: same idea, lighter touch. Orders move under server
-- control only, and every move leaves an event.
-- -----------------------------------------------------------------------------
create or replace function app.order_record_transition()
returns trigger
language plpgsql
security definer
set search_path = ''
as $fn$
begin
  if tg_op = 'INSERT' then
    insert into public.order_status_events (order_id, from_status, to_status, actor_id, actor_role)
    values (new.id, null, new.status, app.current_actor_id(), app.current_role());
    return new;
  end if;

  if new.status is distinct from old.status then
    insert into public.order_status_events
      (order_id, from_status, to_status, actor_id, actor_role, reason)
    values (new.id, old.status, new.status, app.current_actor_id(), app.current_role(),
            new.cancellation_reason);

    if new.status = 'CONFIRMED' and new.confirmed_at is null then
      new.confirmed_at := now();
    elsif new.status = 'COMPLETED' and new.completed_at is null then
      new.completed_at := now();
    elsif new.status in ('CANCELLED','REJECTED') and new.cancelled_at is null then
      new.cancelled_at := now();
    end if;
  end if;

  return new;
end;
$fn$;

-- BEFORE for the timestamp stamping, AFTER-style event write happens in the
-- same function because the row is already assigned by then.
create trigger orders_record_transition_ins
  after insert on public.orders
  for each row execute function app.order_record_transition();

create trigger orders_record_transition_upd
  before update of status on public.orders
  for each row execute function app.order_record_transition();

create trigger orders_touch      before update on public.orders      for each row execute function app.touch_updated_at();
create trigger kot_tickets_touch before update on public.kot_tickets for each row execute function app.touch_updated_at();

create trigger orders_audit      after insert or update or delete on public.orders      for each row execute function app.audit_trigger();
create trigger order_items_audit after insert or update or delete on public.order_items for each row execute function app.audit_trigger();
create trigger kot_tickets_audit after insert or update or delete on public.kot_tickets for each row execute function app.audit_trigger();
create trigger kot_transitions_audit after insert or update or delete on public.kot_transitions for each row execute function app.audit_trigger();


-- >>> 0008_payments.sql ===========================================

-- =============================================================================
-- 0008  Payments, refunds, invoices and idempotency (PRD 8)
-- =============================================================================
--   PAYMENT VERIFIED   -> SUBSCRIPTION / ORDER CREATED -> KOT ELIGIBLE
--   PAYMENT FAILED     -> NO ACTIVE SUBSCRIPTION -> NO KOT -> NO DELIVERY
--
-- That invariant is enforced here by a trigger, not merely respected by the
-- application layer.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Generic API idempotency store. Any financial or order-creating endpoint
-- records its key here first; a retry replays the stored response instead of
-- doing the work twice (PRD 7, PRD 11).
-- -----------------------------------------------------------------------------
create table public.idempotency_keys (
  key            text not null,
  scope          text not null,          -- 'checkout', 'webhook:razorpay', ...
  request_hash   text not null,
  status         text not null default 'in_progress'
                 check (status in ('in_progress','completed','failed')),
  response       jsonb,
  actor_id       uuid references public.auth_profiles(id) on delete set null,
  created_at     timestamptz not null default now(),
  completed_at   timestamptz,
  expires_at     timestamptz not null default now() + interval '7 days',
  primary key (scope, key)
);

create index idempotency_keys_expiry_idx on public.idempotency_keys(expires_at);

create table public.payments (
  id                  uuid primary key default gen_random_uuid(),
  -- A subscription purchase pays for a subscription, not for a single order,
  -- so exactly one of these is set.
  order_id            uuid references public.orders(id) on delete restrict,
  subscription_id     uuid references public.subscriptions(id) on delete restrict,
  customer_id         uuid not null references public.customers(id) on delete restrict,

  provider            public.payment_provider not null,
  flow                public.payment_flow not null default 'one_time',
  status              public.payment_status not null default 'pending',

  amount              numeric(12,2) not null check (amount > 0),
  currency            text not null default 'INR',

  -- Provider-side identifiers. Kept separate so a provider swap is a row
  -- shape change, not a schema migration (PRD 20).
  provider_order_id   text,
  provider_payment_id text,
  provider_signature  text,
  method              text,              -- upi / card / netbanking, as reported

  attempt_number      integer not null default 1 check (attempt_number > 0),
  idempotency_key     text not null,

  -- Set only by server-side verification or a verified webhook. The browser
  -- can never write this column (PRD 8).
  verified_at         timestamptz,
  verified_via        text check (verified_via in ('callback','webhook','reconciliation','manual')),

  failure_code        text,
  failure_message     text,

  -- Uncertain outcomes (debited but unconfirmed) are routed to support rather
  -- than guessed at.
  needs_reconciliation boolean not null default false,
  reconciliation_note  text,

  raw_payload         jsonb,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),

  constraint payments_target check (
    (order_id is not null)::int + (subscription_id is not null)::int = 1
  ),
  constraint payments_success_is_verified check (
    status <> 'success' or verified_at is not null
  )
);

create unique index payments_idempotency_idx on public.payments(idempotency_key);
create unique index payments_provider_payment_idx
  on public.payments(provider, provider_payment_id) where provider_payment_id is not null;
create unique index payments_provider_order_idx
  on public.payments(provider, provider_order_id) where provider_order_id is not null;
create index payments_subscription_idx on public.payments(subscription_id);
create index payments_status_idx on public.payments(status);

-- -----------------------------------------------------------------------------
-- payment_events: the raw webhook/callback log. provider_event_id is unique,
-- which is what makes duplicate webhook delivery a no-op (PRD 8, PRD 11).
-- -----------------------------------------------------------------------------
create table public.payment_events (
  id                uuid primary key default gen_random_uuid(),
  payment_id        uuid references public.payments(id) on delete set null,
  provider          public.payment_provider not null,
  provider_event_id text not null,
  event_type        text not null,
  signature_valid   boolean not null default false,
  payload           jsonb not null,
  received_at       timestamptz not null default now(),
  processed_at      timestamptz,
  processing_error  text
);

create unique index payment_events_provider_event_idx
  on public.payment_events(provider, provider_event_id);
create index payment_events_payment_idx on public.payment_events(payment_id, received_at);

create table public.refunds (
  id                 uuid primary key default gen_random_uuid(),
  payment_id         uuid not null references public.payments(id) on delete restrict,
  amount             numeric(12,2) not null check (amount > 0),
  status             public.payment_status not null default 'pending',
  provider_refund_id text,
  reason             text not null default '',
  idempotency_key    text not null,
  requested_by       uuid references public.auth_profiles(id) on delete set null,
  processed_at       timestamptz,
  raw_payload        jsonb,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

create unique index refunds_idempotency_idx on public.refunds(idempotency_key);
create index refunds_payment_idx on public.refunds(payment_id);

-- -----------------------------------------------------------------------------
-- refund_requests: the ticket workflow the PRD asks for while the actual
-- refund policy is still pending owner approval (PRD 7, PRD 22). Creating a
-- request never moves money; it opens a case.
-- -----------------------------------------------------------------------------
create table public.refund_requests (
  id              uuid primary key default gen_random_uuid(),
  customer_id     uuid not null references public.customers(id) on delete restrict,
  subscription_id uuid references public.subscriptions(id) on delete set null,
  order_id        uuid references public.orders(id) on delete set null,
  payment_id      uuid references public.payments(id) on delete set null,
  reason          text not null,
  requested_amount numeric(12,2) check (requested_amount is null or requested_amount > 0),
  status          text not null default 'open'
                  check (status in ('open','under_review','approved','rejected','completed','withdrawn')),
  resolution_note text,
  handled_by      uuid references public.auth_profiles(id) on delete set null,
  resolved_at     timestamptz,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

create index refund_requests_status_idx on public.refund_requests(status, created_at desc);
create index refund_requests_customer_idx on public.refund_requests(customer_id, created_at desc);

-- -----------------------------------------------------------------------------
-- Invoices (PRD 6). Numbering is its own sequence, independent of orders.
-- -----------------------------------------------------------------------------
create sequence public.invoice_number_seq as bigint start with 1 increment by 1;

create table public.invoices (
  id              uuid primary key default gen_random_uuid(),
  invoice_number  text not null unique,
  invoice_type    text not null default 'customer' check (invoice_type in ('customer','business')),
  customer_id     uuid not null references public.customers(id) on delete restrict,
  order_id        uuid references public.orders(id) on delete restrict,
  subscription_id uuid references public.subscriptions(id) on delete restrict,
  payment_id      uuid references public.payments(id) on delete set null,

  issued_at       timestamptz not null default now(),
  currency        text not null default 'INR',
  subtotal        numeric(12,2) not null check (subtotal >= 0),
  discount_total  numeric(12,2) not null default 0 check (discount_total >= 0),
  delivery_fee    numeric(12,2) not null default 0 check (delivery_fee >= 0),
  tax_total       numeric(12,2) not null default 0 check (tax_total >= 0),
  tax_breakdown   jsonb not null default '[]'::jsonb,
  total           numeric(12,2) not null check (total >= 0),

  -- Snapshot of seller/buyer details as they stood when issued.
  billing_snapshot jsonb not null default '{}'::jsonb,
  document_url    text,
  created_at      timestamptz not null default now()
);

create index invoices_customer_idx on public.invoices(customer_id, issued_at desc);

-- =============================================================================
-- The core payment invariant, enforced in the database
-- =============================================================================
-- A subscription may only reach 'active' when a verified, successful payment
-- exists against it. Free plans (price 0) are exempt; COD is exempt only while
-- it is enabled, and it is paused by default.
-- =============================================================================
create or replace function app.subscription_requires_verified_payment()
returns trigger
language plpgsql
security definer
set search_path = ''
as $fn$
declare
  v_paid boolean;
begin
  if new.status <> 'active' or old.status = 'active' then
    return new;
  end if;

  if new.price_paid = 0 then
    return new;   -- a genuinely free plan needs no payment
  end if;

  select exists (
    select 1 from public.payments p
     where p.subscription_id = new.id
       and p.status = 'success'
       and p.verified_at is not null
  ) into v_paid;

  if not v_paid then
    raise exception
      'subscription % cannot be activated without a verified successful payment',
      new.subscription_number
      using errcode = 'check_violation';
  end if;

  return new;
end;
$fn$;

create trigger subscriptions_require_verified_payment
  before update of status on public.subscriptions
  for each row execute function app.subscription_requires_verified_payment();

-- A KOT ticket may only exist for an order that is confirmed. An unpaid or
-- unverified order therefore cannot reach the kitchen at all.
create or replace function app.kot_requires_confirmed_order()
returns trigger
language plpgsql
security definer
set search_path = ''
as $fn$
declare
  v_status public.order_status;
begin
  select o.status into v_status from public.orders o where o.id = new.order_id;

  if v_status is null then
    raise exception 'KOT ticket references a missing order' using errcode = 'foreign_key_violation';
  end if;

  if v_status not in ('CONFIRMED','IN_PROGRESS') then
    raise exception 'order % is % and is not KOT eligible', new.order_id, v_status
      using errcode = 'check_violation';
  end if;

  return new;
end;
$fn$;

create trigger kot_tickets_require_confirmed_order
  before insert on public.kot_tickets
  for each row execute function app.kot_requires_confirmed_order();

create trigger payments_touch        before update on public.payments        for each row execute function app.touch_updated_at();
create trigger refunds_touch         before update on public.refunds         for each row execute function app.touch_updated_at();
create trigger refund_requests_touch before update on public.refund_requests for each row execute function app.touch_updated_at();

-- Provider signatures and raw payloads are secrets-adjacent; keep them out of
-- the audit trail (PRD 17).
create trigger payments_audit
  after insert or update or delete on public.payments
  for each row execute function app.audit_trigger('{provider_signature,raw_payload}');

create trigger refunds_audit
  after insert or update or delete on public.refunds
  for each row execute function app.audit_trigger('{raw_payload}');

create trigger refund_requests_audit
  after insert or update or delete on public.refund_requests
  for each row execute function app.audit_trigger();

create trigger invoices_audit
  after insert or update or delete on public.invoices
  for each row execute function app.audit_trigger();


-- >>> 0009_coupons_reviews.sql ====================================

-- =============================================================================
-- 0009  Coupons and reviews (PRD 14)
-- =============================================================================

-- -----------------------------------------------------------------------------
-- coupons. The 5% first-subscription offer is one row here, not a constant --
-- its percentage, eligibility and lifetime are all editable (PRD 6, PRD 14).
-- -----------------------------------------------------------------------------
create table public.coupons (
  id                  uuid primary key default gen_random_uuid(),
  code                text not null,
  name                text not null,
  description         text not null default '',

  discount_type       public.coupon_discount_type not null,
  discount_value      numeric(12,2) not null check (discount_value > 0),
  -- Caps a percentage discount. Null = uncapped.
  max_discount_amount numeric(12,2) check (max_discount_amount is null or max_discount_amount > 0),
  min_order_amount    numeric(12,2) not null default 0 check (min_order_amount >= 0),

  applies_to          text not null default 'subscription'
                      check (applies_to in ('subscription','order','all')),

  -- Usage limits. Null = unlimited.
  per_customer_limit  integer check (per_customer_limit is null or per_customer_limit > 0),
  total_usage_limit   integer check (total_usage_limit is null or total_usage_limit > 0),
  times_redeemed      integer not null default 0 check (times_redeemed >= 0),

  -- Shown to the customer as already unlocked rather than hidden behind a
  -- code box (PRD 6). It still has to pass server validation to be applied.
  is_auto_visible     boolean not null default false,

  valid_from          timestamptz not null default now(),
  valid_until         timestamptz,
  is_active           boolean not null default true,

  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint coupons_window check (valid_until is null or valid_until > valid_from),
  constraint coupons_percent_range
    check (discount_type <> 'percent' or discount_value <= 100)
);

create unique index coupons_code_idx on public.coupons(upper(code));

-- -----------------------------------------------------------------------------
-- coupon_rules: additional eligibility predicates, kept as rows so a new
-- campaign shape does not need a schema change.
-- -----------------------------------------------------------------------------
create table public.coupon_rules (
  id         uuid primary key default gen_random_uuid(),
  coupon_id  uuid not null references public.coupons(id) on delete cascade,
  rule_type  text not null check (rule_type in
               ('first_subscription','plan_in','source_in','customer_in','new_customer_only')),
  config     jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index coupon_rules_coupon_idx on public.coupon_rules(coupon_id);

create table public.coupon_redemptions (
  id              uuid primary key default gen_random_uuid(),
  coupon_id       uuid not null references public.coupons(id) on delete restrict,
  customer_id     uuid not null references public.customers(id) on delete restrict,
  subscription_id uuid references public.subscriptions(id) on delete set null,
  order_id        uuid references public.orders(id) on delete set null,
  discount_amount numeric(12,2) not null check (discount_amount >= 0),
  redeemed_at     timestamptz not null default now()
);

create index coupon_redemptions_customer_idx on public.coupon_redemptions(coupon_id, customer_id);
-- A single subscription can consume a coupon exactly once, even under retry.
create unique index coupon_redemptions_subscription_idx
  on public.coupon_redemptions(coupon_id, subscription_id) where subscription_id is not null;

alter table public.orders
  add constraint orders_coupon_fk
  foreign key (coupon_id) references public.coupons(id) on delete set null;

-- -----------------------------------------------------------------------------
-- Server-side coupon validation (PRD 6, PRD 14). The browser may *show* an
-- offer as unlocked; only this decides whether it applies.
-- Returns one row: is_valid, reason, discount_amount.
-- -----------------------------------------------------------------------------
create or replace function public.validate_coupon(
  p_code        text,
  p_customer_id uuid,
  p_subtotal    numeric,
  p_plan_id     uuid default null,
  p_source      public.order_source default 'SX',
  p_at          timestamptz default now()
)
returns table (is_valid boolean, reason text, discount_amount numeric, coupon_id uuid)
language plpgsql
stable
security definer
set search_path = ''
as $fn$
declare
  c            public.coupons%rowtype;
  v_rule       public.coupon_rules%rowtype;
  v_used       integer;
  v_discount   numeric(12,2);
  v_has_prior  boolean;
begin
  select * into c from public.coupons
   where upper(code) = upper(p_code) and is_active;

  if not found then
    return query select false, 'Coupon not found', 0::numeric, null::uuid; return;
  end if;

  if c.valid_from > p_at then
    return query select false, 'Coupon is not active yet', 0::numeric, c.id; return;
  end if;

  if c.valid_until is not null and c.valid_until <= p_at then
    return query select false, 'Coupon has expired', 0::numeric, c.id; return;
  end if;

  if c.applies_to = 'subscription' and p_plan_id is null then
    return query select false, 'Coupon applies to subscriptions only', 0::numeric, c.id; return;
  end if;

  if p_subtotal < c.min_order_amount then
    return query select false,
      format('Requires a minimum of %s', c.min_order_amount), 0::numeric, c.id; return;
  end if;

  if c.total_usage_limit is not null and c.times_redeemed >= c.total_usage_limit then
    return query select false, 'Coupon usage limit reached', 0::numeric, c.id; return;
  end if;

  if c.per_customer_limit is not null then
    select count(*) into v_used
      from public.coupon_redemptions r
     where r.coupon_id = c.id and r.customer_id = p_customer_id;

    if v_used >= c.per_customer_limit then
      return query select false, 'You have already used this offer', 0::numeric, c.id; return;
    end if;
  end if;

  -- Extra eligibility predicates. The column is qualified because this
  -- function also returns an output column called coupon_id.
  for v_rule in select cr.* from public.coupon_rules cr where cr.coupon_id = c.id loop
    if v_rule.rule_type = 'first_subscription' then
      -- "First subscription" means no subscription has ever been activated for
      -- this customer -- checked on the server, never inferred from the client.
      select exists (
        select 1 from public.subscriptions s
         where s.customer_id = p_customer_id
           and s.activated_at is not null
      ) into v_has_prior;

      if v_has_prior then
        return query select false, 'Offer is for your first subscription only',
                            0::numeric, c.id; return;
      end if;

    elsif v_rule.rule_type = 'plan_in' then
      if p_plan_id is null
         or not (v_rule.config -> 'plan_ids' ? p_plan_id::text) then
        return query select false, 'Offer does not apply to this plan', 0::numeric, c.id; return;
      end if;

    elsif v_rule.rule_type = 'source_in' then
      if not (v_rule.config -> 'sources' ? p_source::text) then
        return query select false, 'Offer does not apply to this channel', 0::numeric, c.id; return;
      end if;

    elsif v_rule.rule_type = 'customer_in' then
      if not (v_rule.config -> 'customer_ids' ? p_customer_id::text) then
        return query select false, 'Offer is not available on this account', 0::numeric, c.id; return;
      end if;

    elsif v_rule.rule_type = 'new_customer_only' then
      select exists (
        select 1 from public.orders o
         where o.customer_id = p_customer_id and o.status <> 'DRAFT'
      ) into v_has_prior;

      if v_has_prior then
        return query select false, 'Offer is for new customers only', 0::numeric, c.id; return;
      end if;
    end if;
  end loop;

  if c.discount_type = 'percent' then
    v_discount := round(p_subtotal * c.discount_value / 100.0, 2);
    if c.max_discount_amount is not null then
      v_discount := least(v_discount, c.max_discount_amount);
    end if;
  else
    v_discount := least(c.discount_value, p_subtotal);
  end if;

  return query select true, 'ok'::text, v_discount, c.id;
end;
$fn$;

-- =============================================================================
-- Reviews with moderation (PRD 14)
-- =============================================================================
create table public.reviews (
  id                  uuid primary key default gen_random_uuid(),
  customer_id         uuid not null references public.customers(id) on delete cascade,
  product_id          uuid references public.products(id) on delete cascade,
  subscription_id     uuid references public.subscriptions(id) on delete set null,
  order_id            uuid references public.orders(id) on delete set null,

  rating              smallint not null check (rating between 1 and 5),
  title               text not null default '',
  body                text not null default '',

  -- Reviews start pending and are published by moderation policy, so nothing
  -- unmoderated ever renders publicly.
  status              public.review_status not null default 'pending',
  is_verified_purchase boolean not null default false,

  edited_at           timestamptz,
  deleted_at          timestamptz,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);

create index reviews_product_idx on public.reviews(product_id, status, created_at desc);
create index reviews_customer_idx on public.reviews(customer_id, created_at desc);
create index reviews_moderation_queue_idx on public.reviews(status, created_at)
  where status = 'pending';

create table public.review_moderation (
  id            uuid primary key default gen_random_uuid(),
  review_id     uuid not null references public.reviews(id) on delete cascade,
  from_status   public.review_status,
  to_status     public.review_status not null,
  moderator_id  uuid references public.auth_profiles(id) on delete set null,
  reason        text,
  created_at    timestamptz not null default now()
);

create index review_moderation_review_idx on public.review_moderation(review_id, created_at);

-- Every status change is recorded, so hiding a review is itself auditable.
create or replace function app.review_record_moderation()
returns trigger
language plpgsql
security definer
set search_path = ''
as $fn$
begin
  if new.status is distinct from old.status then
    insert into public.review_moderation (review_id, from_status, to_status, moderator_id)
    values (new.id, old.status, new.status, app.current_actor_id());
  end if;
  return new;
end;
$fn$;

create trigger reviews_record_moderation
  after update of status on public.reviews
  for each row execute function app.review_record_moderation();

create trigger coupons_touch  before update on public.coupons  for each row execute function app.touch_updated_at();
create trigger reviews_touch  before update on public.reviews  for each row execute function app.touch_updated_at();

create trigger coupons_audit            after insert or update or delete on public.coupons            for each row execute function app.audit_trigger();
create trigger coupon_rules_audit       after insert or update or delete on public.coupon_rules       for each row execute function app.audit_trigger();
create trigger coupon_redemptions_audit after insert or update or delete on public.coupon_redemptions for each row execute function app.audit_trigger();
create trigger reviews_audit            after insert or update or delete on public.reviews            for each row execute function app.audit_trigger();


-- >>> 0010_notifications_integrations.sql =========================

-- =============================================================================
-- 0010  Notifications and marketplace integrations (PRD 15, PRD 16)
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Templates are rows so message copy is not a deploy. The provider and the
-- exact notification matrix are chosen later (PRD 15); nothing here assumes
-- WhatsApp specifically.
-- -----------------------------------------------------------------------------
create table public.notification_templates (
  code           text primary key,
  channel        public.notification_channel not null,
  name           text not null,
  subject        text,
  body_template  text not null,
  -- Documented placeholders, for the admin UI and for validation.
  variables      text[] not null default '{}',
  is_active      boolean not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- notifications doubles as the outbox. Core flows enqueue a row inside their
-- own transaction and return; a failed send retries here and can never roll
-- back an order or a payment (PRD 15).
-- -----------------------------------------------------------------------------
create table public.notifications (
  id                  uuid primary key default gen_random_uuid(),
  customer_id         uuid references public.customers(id) on delete set null,
  profile_id          uuid references public.auth_profiles(id) on delete set null,
  channel             public.notification_channel not null,
  template_code       text references public.notification_templates(code) on delete set null,

  -- Destination is snapshotted: changing a phone number later must not
  -- rewrite where a message was actually sent.
  to_address          text not null,
  payload             jsonb not null default '{}'::jsonb,
  rendered_body       text,

  status              public.notification_status not null default 'queued',
  attempts            integer not null default 0 check (attempts >= 0),
  max_attempts        integer not null default 5 check (max_attempts > 0),
  next_attempt_at     timestamptz not null default now(),
  last_error          text,

  provider            text,
  provider_message_id text,

  -- Dedupe key: enqueuing "subscription activated" twice for the same
  -- subscription is a no-op.
  dedupe_key          text,

  scheduled_for       timestamptz not null default now(),
  sent_at             timestamptz,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);

create unique index notifications_dedupe_idx on public.notifications(dedupe_key)
  where dedupe_key is not null;
create index notifications_queue_idx on public.notifications(status, next_attempt_at)
  where status in ('queued','failed');
create index notifications_customer_idx on public.notifications(customer_id, created_at desc);

create table public.notification_events (
  id              uuid primary key default gen_random_uuid(),
  notification_id uuid not null references public.notifications(id) on delete cascade,
  event_type      text not null,          -- queued / sent / delivered / read / failed
  payload         jsonb not null default '{}'::jsonb,
  occurred_at     timestamptz not null default now()
);

create index notification_events_notification_idx
  on public.notification_events(notification_id, occurred_at);

-- =============================================================================
-- Marketplace integration (PRD 16)
-- =============================================================================
-- Swiggy and Zomato are external order channels. Credentials are NEVER stored
-- here -- only the name of the secret to look up in secure storage.
-- =============================================================================
create table public.integration_accounts (
  id                     uuid primary key default gen_random_uuid(),
  provider               public.integration_provider not null,
  display_name           text not null,
  external_restaurant_id text,
  -- e.g. 'SWIGGY_API_KEY'. Resolved from the environment at runtime; the value
  -- never touches the database and never reaches a staff-visible response.
  credentials_ref        text,
  webhook_secret_ref     text,
  config                 jsonb not null default '{}'::jsonb,

  is_enabled             boolean not null default false,
  health                 public.integration_health not null default 'disabled',
  last_healthy_at        timestamptz,
  last_error             text,
  last_error_at          timestamptz,
  -- One marketplace failing must not stop the others (PRD 16); each account
  -- carries its own breaker state.
  consecutive_failures   integer not null default 0,
  circuit_open_until     timestamptz,

  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  unique (provider)
);

-- -----------------------------------------------------------------------------
-- Capability register. Phase 1 must state, per feature, whether it is really
-- integrated, mocked, or blocked by the external API (PRD 16, PRD 23). The UI
-- reads this instead of implying capabilities we have not verified.
-- -----------------------------------------------------------------------------
create table public.integration_capabilities (
  id           uuid primary key default gen_random_uuid(),
  provider     public.integration_provider not null,
  capability   text not null,     -- order_ingestion, accept_reject, cancellation, ...
  state        public.integration_capability_state not null,
  notes        text not null default '',
  -- Link to the official documentation that justifies the state. Empty means
  -- unverified, which is itself information.
  reference_url text,
  verified_at  timestamptz,
  updated_at   timestamptz not null default now(),
  unique (provider, capability)
);

create table public.integration_events (
  id                uuid primary key default gen_random_uuid(),
  provider          public.integration_provider not null,
  account_id        uuid references public.integration_accounts(id) on delete set null,
  direction         text not null check (direction in ('inbound','outbound')),
  event_type        text not null,
  -- Unique per provider: replayed marketplace webhooks are idempotent.
  external_event_id text,
  external_order_id text,
  order_id          uuid references public.orders(id) on delete set null,
  signature_valid   boolean not null default false,
  payload           jsonb not null default '{}'::jsonb,
  status            text not null default 'received'
                    check (status in ('received','processed','ignored','failed')),
  error             text,
  received_at       timestamptz not null default now(),
  processed_at      timestamptz
);

create unique index integration_events_external_idx
  on public.integration_events(provider, external_event_id)
  where external_event_id is not null;
create index integration_events_order_idx on public.integration_events(external_order_id);
create index integration_events_provider_idx on public.integration_events(provider, received_at desc);

-- -----------------------------------------------------------------------------
-- Two-way reconciliation (PRD 16): compare what the marketplace says it sent
-- against what we hold, and record the differences rather than silently
-- trusting either side.
-- -----------------------------------------------------------------------------
create table public.integration_reconciliation (
  id               uuid primary key default gen_random_uuid(),
  provider         public.integration_provider not null,
  window_start     timestamptz not null,
  window_end       timestamptz not null,
  external_count   integer not null default 0,
  internal_count   integer not null default 0,
  missing_internal jsonb not null default '[]'::jsonb,  -- present externally, absent here
  missing_external jsonb not null default '[]'::jsonb,  -- present here, absent externally
  mismatched       jsonb not null default '[]'::jsonb,  -- present both sides, differing
  status           text not null default 'clean'
                   check (status in ('clean','discrepancies','failed')),
  notes            text,
  ran_at           timestamptz not null default now(),
  constraint integration_reconciliation_window check (window_end > window_start)
);

create index integration_reconciliation_provider_idx
  on public.integration_reconciliation(provider, ran_at desc);

create trigger notification_templates_touch  before update on public.notification_templates  for each row execute function app.touch_updated_at();
create trigger notifications_touch           before update on public.notifications           for each row execute function app.touch_updated_at();
create trigger integration_accounts_touch    before update on public.integration_accounts    for each row execute function app.touch_updated_at();
create trigger integration_capabilities_touch before update on public.integration_capabilities for each row execute function app.touch_updated_at();

create trigger notification_templates_audit
  after insert or update or delete on public.notification_templates
  for each row execute function app.audit_trigger();

-- Even the *reference* to a credential is worth keeping out of the log.
create trigger integration_accounts_audit
  after insert or update or delete on public.integration_accounts
  for each row execute function app.audit_trigger('{credentials_ref,webhook_secret_ref,config}');

create trigger integration_capabilities_audit
  after insert or update or delete on public.integration_capabilities
  for each row execute function app.audit_trigger();


-- >>> 0011_pricing_and_checkout.sql ===============================

-- =============================================================================
-- 0011  Server-authoritative pricing and subscription checkout (PRD 6, 7, 8)
-- =============================================================================
-- The browser never decides what anything costs. It asks for a quote, shows
-- it, and submits a choice; this file recomputes the same numbers server-side
-- before a payment is ever created.
-- =============================================================================

create sequence public.subscription_number_seq as bigint start with 1 increment by 1;

create or replace function app.next_subscription_number()
returns text
language sql
volatile
security definer
set search_path = ''
as $fn$
  select 'SUB-' || lpad(nextval('public.subscription_number_seq')::text, 6, '0');
$fn$;

create or replace function app.next_invoice_number()
returns text
language sql
volatile
security definer
set search_path = ''
as $fn$
  select 'INV-' || to_char(now(), 'YYYY') || '-'
      || lpad(nextval('public.invoice_number_seq')::text, 6, '0');
$fn$;

-- =============================================================================
-- quote_subscription
-- =============================================================================
-- Returns the full price breakdown for buying a plan, including the CGST/SGST
-- split and whether a requested coupon actually applies. This is the only
-- place subscription pricing is computed.
-- =============================================================================
create or replace function public.quote_subscription(
  p_plan_id     uuid,
  p_customer_id uuid default null,
  p_coupon_code text default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $fn$
declare
  v_plan        public.subscription_plans%rowtype;
  v_subtotal    numeric(12,2);
  v_discount    numeric(12,2) := 0;
  v_coupon_id   uuid;
  v_coupon_ok   boolean := false;
  v_coupon_msg  text := null;
  v_delivery    numeric(12,2) := 0;
  v_taxable     numeric(12,2);
  v_tax_total   numeric(12,2) := 0;
  v_breakdown   jsonb := '[]'::jsonb;
  v_component   record;
  v_amount      numeric(12,2);
  v_charge_delivery boolean;
begin
  select * into v_plan
    from public.subscription_plans
   where id = p_plan_id
     and is_active
     and is_published
     and archived_at is null;

  if not found then
    raise exception 'plan % is not available for purchase', p_plan_id
      using errcode = 'no_data_found';
  end if;

  v_subtotal := v_plan.price;

  -- Coupon. An invalid code is not an error -- the caller gets a reason to
  -- show, and the quote simply carries no discount.
  if p_coupon_code is not null and p_customer_id is not null then
    select vc.is_valid, vc.reason, vc.discount_amount, vc.coupon_id
      into v_coupon_ok, v_coupon_msg, v_discount, v_coupon_id
      from public.validate_coupon(p_coupon_code, p_customer_id, v_subtotal, p_plan_id, 'SX') vc;

    if not v_coupon_ok then
      v_discount := 0;
      v_coupon_id := null;
    end if;
  end if;

  v_charge_delivery := coalesce(
    (app.setting('subscription.charge_delivery_fee_at_checkout') #>> '{}')::boolean, false);

  if v_charge_delivery then
    v_delivery := app.resolve_delivery_fee(v_subtotal - v_discount, 'SX');
  end if;

  v_taxable := greatest(v_subtotal - v_discount, 0);

  -- One row per active tax component, so the invoice can show CGST and SGST
  -- separately instead of a single opaque line (PRD 6).
  for v_component in select * from app.resolve_tax_components('food') loop
    v_amount := round(v_taxable * v_component.rate_percent / 100.0, 2);
    v_tax_total := v_tax_total + v_amount;
    v_breakdown := v_breakdown || jsonb_build_object(
      'code',   v_component.code,
      'label',  v_component.label,
      'rate',   v_component.rate_percent,
      'amount', v_amount
    );
  end loop;

  return jsonb_build_object(
    'plan_id',        v_plan.id,
    'plan_name',      v_plan.name,
    'currency',       'INR',
    'subtotal',       v_subtotal,
    'discount_total', v_discount,
    'coupon_code',    case when v_coupon_id is not null then upper(p_coupon_code) end,
    'coupon_id',      v_coupon_id,
    'coupon_applied', v_coupon_ok,
    'coupon_message', v_coupon_msg,
    'delivery_fee',   v_delivery,
    'tax_total',      v_tax_total,
    'tax_breakdown',  v_breakdown,
    'grand_total',    round(v_taxable + v_delivery + v_tax_total, 2)
  );
end;
$fn$;

-- =============================================================================
-- begin_subscription_checkout
-- =============================================================================
-- Creates a subscription in 'pending_payment' plus a 'pending' payment row,
-- and returns the amount the gateway should be asked for. It grants nothing,
-- schedules nothing and produces no KOT -- a subscription only becomes real
-- once the payment is verified.
--
-- Idempotent on p_idempotency_key: a retried checkout returns the original
-- subscription and payment rather than creating a second one (PRD 7).
-- =============================================================================
create or replace function public.begin_subscription_checkout(
  p_customer_id      uuid,
  p_plan_id          uuid,
  p_address_id       uuid,
  p_delivery_window_id uuid,
  p_provider         public.payment_provider,
  p_idempotency_key  text,
  p_delivery_days    smallint[] default '{}',
  p_selected_meals   jsonb default '[]'::jsonb,
  p_coupon_code      text default null,
  p_delivery_instructions text default null,
  p_starts_on        date default null
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $fn$
declare
  v_existing      public.payments%rowtype;
  v_plan          public.subscription_plans%rowtype;
  v_quote         jsonb;
  v_subscription  public.subscriptions%rowtype;
  v_payment_id    uuid;
  v_grace         integer;
  v_starts_on     date;
  v_meal          jsonb;
  v_sub_id        uuid;
begin
  if p_idempotency_key is null or length(p_idempotency_key) < 8 then
    raise exception 'a checkout idempotency key is required' using errcode = 'invalid_parameter_value';
  end if;

  perform app.assert_customer_access(p_customer_id);

  -- Replay: hand back exactly what the first call produced.
  select * into v_existing from public.payments where idempotency_key = p_idempotency_key;
  if found then
    return jsonb_build_object(
      'replayed',        true,
      'subscription_id', v_existing.subscription_id,
      'payment_id',      v_existing.id,
      'amount',          v_existing.amount,
      'status',          v_existing.status
    );
  end if;

  select * into v_plan from public.subscription_plans where id = p_plan_id;
  if not found then
    raise exception 'plan % not found', p_plan_id using errcode = 'no_data_found';
  end if;

  -- Address must belong to this customer. Never trust a client-supplied id.
  if p_address_id is not null and not exists (
    select 1 from public.customer_addresses
     where id = p_address_id and customer_id = p_customer_id and is_active
  ) then
    raise exception 'delivery address does not belong to this customer'
      using errcode = 'insufficient_privilege';
  end if;

  -- The plan must actually offer the requested window.
  if p_delivery_window_id is not null and exists (
       select 1 from public.subscription_plan_windows where plan_id = p_plan_id
     ) and not exists (
       select 1 from public.subscription_plan_windows
        where plan_id = p_plan_id and delivery_window_id = p_delivery_window_id
     ) then
    raise exception 'this plan is not offered in the selected delivery window'
      using errcode = 'check_violation';
  end if;

  v_quote := public.quote_subscription(p_plan_id, p_customer_id, p_coupon_code);

  v_grace := coalesce(v_plan.grace_period_days, app.setting_int('subscription.grace_period_days'));
  v_starts_on := coalesce(p_starts_on, app.business_date() + 1);

  insert into public.subscriptions (
    subscription_number, customer_id, plan_id, status,
    plan_snapshot, price_paid, payment_flow,
    starts_on, current_period_start, current_period_end,
    delivery_address_id, delivery_window_id, delivery_days, delivery_instructions,
    grace_period_days
  ) values (
    app.next_subscription_number(), p_customer_id, p_plan_id, 'pending_payment',
    -- Freeze the commercial terms and the quote that produced this price.
    jsonb_build_object('plan', to_jsonb(v_plan), 'quote', v_quote),
    (v_quote ->> 'grand_total')::numeric,
    v_plan.payment_flow,
    v_starts_on, v_starts_on, v_starts_on + (v_plan.billing_period_days - 1),
    p_address_id, p_delivery_window_id, coalesce(p_delivery_days, '{}'), p_delivery_instructions,
    v_grace
  )
  returning * into v_subscription;

  v_sub_id := v_subscription.id;

  -- Customer-selected plans record the customer's picks now; they are
  -- validated against the plan's selectable pool.
  if v_plan.plan_type = 'customer_selected' and jsonb_array_length(coalesce(p_selected_meals, '[]'::jsonb)) > 0 then
    for v_meal in select * from jsonb_array_elements(p_selected_meals) loop
      if not exists (
        select 1 from public.subscription_plan_meals m
         where m.plan_id = p_plan_id
           and m.product_id = (v_meal ->> 'product_id')::uuid
           and m.is_selectable
      ) then
        raise exception 'meal % is not selectable on this plan', v_meal ->> 'product_id'
          using errcode = 'check_violation';
      end if;

      if not app.product_is_orderable((v_meal ->> 'product_id')::uuid) then
        raise exception 'meal % is currently unavailable', v_meal ->> 'product_id'
          using errcode = 'check_violation';
      end if;

      insert into public.subscription_selected_meals
        (subscription_id, product_id, day_of_week, delivery_window_id, quantity)
      values (
        v_sub_id,
        (v_meal ->> 'product_id')::uuid,
        nullif(v_meal ->> 'day_of_week', '')::smallint,
        coalesce(nullif(v_meal ->> 'delivery_window_id', '')::uuid, p_delivery_window_id),
        coalesce((v_meal ->> 'quantity')::integer, 1)
      );
    end loop;
  end if;

  insert into public.payments (
    subscription_id, customer_id, provider, flow, status,
    amount, currency, idempotency_key
  ) values (
    v_sub_id, p_customer_id, p_provider, v_plan.payment_flow, 'pending',
    (v_quote ->> 'grand_total')::numeric, 'INR', p_idempotency_key
  )
  returning id into v_payment_id;

  perform public.record_audit_event(
    'insert', 'subscription_checkout', v_sub_id::text, null,
    jsonb_build_object('payment_id', v_payment_id, 'quote', v_quote));

  return jsonb_build_object(
    'replayed',            false,
    'subscription_id',     v_sub_id,
    'subscription_number', v_subscription.subscription_number,
    'payment_id',          v_payment_id,
    'amount',              (v_quote ->> 'grand_total')::numeric,
    'currency',            'INR',
    'quote',               v_quote
  );
end;
$fn$;


-- >>> 0012_subscription_engine.sql ================================

-- =============================================================================
-- 0012  Subscription engine: activation, credits, schedule generation,
--       skip / pause / cancel, and release to the KOT (PRD 7, 8, 9)
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Ownership guard. The customer-facing RPCs below are SECURITY DEFINER, which
-- means they run with the definer's rights and RLS does not filter them. Each
-- one must therefore prove for itself that the caller is entitled to the
-- subscription it is about to act on -- otherwise passing someone else's id
-- would be enough to pause their plan.
-- -----------------------------------------------------------------------------
create or replace function app.assert_subscription_access(p_subscription_id uuid)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $fn$
begin
  if app.is_service_role() or app.has_permission('subscriptions.manage') then
    return;
  end if;

  if exists (
    select 1 from public.subscriptions s
     where s.id = p_subscription_id
       and s.customer_id = app.current_customer_id()
  ) then
    return;
  end if;

  raise exception 'not permitted to act on this subscription'
    using errcode = 'insufficient_privilege';
end;
$fn$;

create or replace function app.assert_customer_access(p_customer_id uuid)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $fn$
begin
  if app.is_service_role()
     or app.has_permission('customers.manage')
     or p_customer_id = app.current_customer_id() then
    return;
  end if;

  raise exception 'not permitted to act on behalf of this customer'
    using errcode = 'insufficient_privilege';
end;
$fn$;

-- -----------------------------------------------------------------------------
-- Entitlement granted per billing cycle. Credit-plans grant credits directly;
-- meal-count plans grant one credit per meal, and each meal consumes as many
-- credits as its product says -- which is how a premium meal costs more than
-- one without a second code path (PRD 7).
-- -----------------------------------------------------------------------------
create or replace function app.plan_cycle_credits(p_plan public.subscription_plans)
returns integer
language sql
immutable
as $fn$
  select case
    when p_plan.plan_type = 'meal_credits' then p_plan.credits_per_cycle
    else p_plan.meals_per_cycle
  end;
$fn$;

-- Base KOT priority per source. Marketplace orders outrank scheduled
-- subscription deliveries because they are immediate (PRD 9) -- and the
-- numbers are a setting, not a constant.
create or replace function app.base_priority(p_source public.order_source)
returns integer
language sql
stable
security definer
set search_path = ''
as $fn$
  select coalesce((app.setting('kot.base_priority') ->> p_source::text)::integer, 0);
$fn$;

create or replace function app.sla_due_at(
  p_source public.order_source,
  p_from   timestamptz default now()
)
returns timestamptz
language sql
stable
security definer
set search_path = ''
as $fn$
  select p_from + make_interval(
    mins => coalesce((app.setting('kot.sla_minutes') ->> p_source::text)::integer, 45));
$fn$;

-- =============================================================================
-- confirm_subscription_payment
-- =============================================================================
-- The single door through which a subscription becomes real. Called only by
-- server-side code that has already verified the provider signature; it
-- refuses to proceed if that verification did not happen.
--
-- Idempotent: a duplicate webhook or a callback racing a webhook results in
-- one activation, one credit grant, one invoice and one schedule.
-- =============================================================================
create or replace function public.confirm_subscription_payment(
  p_payment_id          uuid,
  p_provider_payment_id text,
  p_signature_verified  boolean,
  p_verified_via        text default 'webhook',
  p_raw                 jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $fn$
declare
  v_payment      public.payments%rowtype;
  v_subscription public.subscriptions%rowtype;
  v_plan         public.subscription_plans%rowtype;
  v_quote        jsonb;
  v_credits      integer;
  v_invoice_id   uuid;
  v_coupon_id    uuid;
  v_deliveries   integer := 0;
begin
  if not p_signature_verified then
    raise exception 'refusing to confirm a payment whose signature was not verified'
      using errcode = 'insufficient_privilege';
  end if;

  -- Serialise concurrent confirmations of the same payment.
  select * into v_payment from public.payments where id = p_payment_id for update;
  if not found then
    raise exception 'payment % not found', p_payment_id using errcode = 'no_data_found';
  end if;

  if v_payment.status = 'success' then
    return jsonb_build_object(
      'replayed', true,
      'payment_id', v_payment.id,
      'subscription_id', v_payment.subscription_id,
      'status', 'success');
  end if;

  if v_payment.status in ('refunded','partially_refunded') then
    raise exception 'payment % has already been refunded', p_payment_id
      using errcode = 'check_violation';
  end if;

  update public.payments
     set status              = 'success',
         provider_payment_id = coalesce(p_provider_payment_id, provider_payment_id),
         verified_at         = now(),
         verified_via        = p_verified_via,
         raw_payload         = p_raw,
         needs_reconciliation = false,
         failure_code        = null,
         failure_message     = null
   where id = p_payment_id;

  select * into v_subscription from public.subscriptions
   where id = v_payment.subscription_id for update;

  if not found then
    raise exception 'payment % is not attached to a subscription', p_payment_id
      using errcode = 'check_violation';
  end if;

  select * into v_plan from public.subscription_plans where id = v_subscription.plan_id;

  -- Activate. The trigger from 0008 re-checks that a verified payment exists.
  if v_subscription.status = 'pending_payment' then
    update public.subscriptions
       set status         = 'active',
           activated_at   = now(),
           next_renewal_at = case
             when v_plan.payment_flow = 'recurring'
             then (v_subscription.current_period_end + 1)::timestamptz
             else null end
     where id = v_subscription.id;
  end if;

  -- Grant the cycle's entitlement. The idempotency key makes a replay a no-op.
  v_credits := app.plan_cycle_credits(v_plan);
  if v_credits is not null and v_credits > 0 then
    insert into public.subscription_credit_ledger
      (subscription_id, entry_type, credits, reason, idempotency_key)
    values
      (v_subscription.id, 'grant', v_credits,
       format('Cycle grant for %s', v_plan.name),
       'grant:' || v_subscription.id::text || ':' || v_subscription.current_period_start::text)
    on conflict (subscription_id, idempotency_key) do nothing;
  end if;

  -- Record the coupon redemption exactly once.
  v_quote := v_subscription.plan_snapshot -> 'quote';
  v_coupon_id := nullif(v_quote ->> 'coupon_id', '')::uuid;

  if v_coupon_id is not null and (v_quote ->> 'coupon_applied')::boolean then
    insert into public.coupon_redemptions
      (coupon_id, customer_id, subscription_id, discount_amount)
    values
      (v_coupon_id, v_subscription.customer_id, v_subscription.id,
       (v_quote ->> 'discount_total')::numeric)
    on conflict (coupon_id, subscription_id) where subscription_id is not null do nothing;

    if found then
      update public.coupons set times_redeemed = times_redeemed + 1 where id = v_coupon_id;
    end if;
  end if;

  -- Invoice, once.
  select id into v_invoice_id from public.invoices where payment_id = p_payment_id;
  if v_invoice_id is null then
    insert into public.invoices (
      invoice_number, invoice_type, customer_id, subscription_id, payment_id,
      subtotal, discount_total, delivery_fee, tax_total, tax_breakdown, total,
      billing_snapshot
    ) values (
      app.next_invoice_number(), 'customer', v_subscription.customer_id,
      v_subscription.id, p_payment_id,
      (v_quote ->> 'subtotal')::numeric,
      (v_quote ->> 'discount_total')::numeric,
      (v_quote ->> 'delivery_fee')::numeric,
      (v_quote ->> 'tax_total')::numeric,
      coalesce(v_quote -> 'tax_breakdown', '[]'::jsonb),
      (v_quote ->> 'grand_total')::numeric,
      jsonb_build_object('plan', v_plan.name, 'subscription_number', v_subscription.subscription_number)
    )
    returning id into v_invoice_id;
  end if;

  -- Build the delivery schedule from plan rules.
  v_deliveries := public.generate_subscription_deliveries(
    v_subscription.id,
    greatest(v_subscription.current_period_start, app.business_date()),
    v_subscription.current_period_end);

  -- Notification is enqueued, never sent inline: a provider outage must not
  -- roll back an activation (PRD 15).
  insert into public.notifications
    (customer_id, channel, template_code, to_address, payload, dedupe_key)
  select v_subscription.customer_id,
         'whatsapp',
         'subscription_activated',
         c.phone,
         jsonb_build_object(
           'customer_name', c.full_name,
           'plan_name', v_plan.name,
           'subscription_number', v_subscription.subscription_number,
           'starts_on', v_subscription.starts_on),
         'subscription_activated:' || v_subscription.id::text
    from public.customers c
   where c.id = v_subscription.customer_id
  on conflict (dedupe_key) where dedupe_key is not null do nothing;

  perform public.record_audit_event(
    'state_transition', 'subscriptions', v_subscription.id::text,
    jsonb_build_object('status', 'pending_payment'),
    jsonb_build_object('status', 'active', 'payment_id', p_payment_id,
                       'credits_granted', v_credits, 'deliveries_generated', v_deliveries));

  return jsonb_build_object(
    'replayed', false,
    'payment_id', p_payment_id,
    'subscription_id', v_subscription.id,
    'subscription_number', v_subscription.subscription_number,
    'credits_granted', coalesce(v_credits, 0),
    'deliveries_generated', v_deliveries,
    'invoice_id', v_invoice_id,
    'status', 'active');
end;
$fn$;

-- -----------------------------------------------------------------------------
-- Failure path. Leaves the subscription inactive and creates nothing
-- downstream -- no schedule, no ticket, no delivery (PRD 8).
-- -----------------------------------------------------------------------------
create or replace function public.fail_subscription_payment(
  p_payment_id  uuid,
  p_code        text,
  p_message     text,
  p_uncertain   boolean default false,
  p_raw         jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $fn$
declare
  v_payment public.payments%rowtype;
begin
  select * into v_payment from public.payments where id = p_payment_id for update;
  if not found then
    raise exception 'payment % not found', p_payment_id using errcode = 'no_data_found';
  end if;

  -- A late failure notice must never undo a confirmed payment.
  if v_payment.status = 'success' then
    return jsonb_build_object('ignored', true, 'reason', 'payment already succeeded');
  end if;

  update public.payments
     set status = 'failed',
         failure_code = p_code,
         failure_message = p_message,
         -- "Money may have left the customer but we cannot confirm it" is its
         -- own state, routed to reconciliation rather than guessed at.
         needs_reconciliation = p_uncertain,
         raw_payload = p_raw
   where id = p_payment_id;

  perform public.record_audit_event(
    'state_transition', 'payments', p_payment_id::text,
    jsonb_build_object('status', v_payment.status),
    jsonb_build_object('status', 'failed', 'code', p_code, 'needs_reconciliation', p_uncertain));

  return jsonb_build_object(
    'payment_id', p_payment_id,
    'status', 'failed',
    'subscription_active', false,
    'needs_reconciliation', p_uncertain);
end;
$fn$;

-- =============================================================================
-- generate_subscription_deliveries
-- =============================================================================
-- Expands plan rules into dated delivery rows. Re-running it for an
-- overlapping range is safe: the unique key on
-- (subscription_id, scheduled_date, delivery_window_id) absorbs duplicates.
-- =============================================================================
create or replace function public.generate_subscription_deliveries(
  p_subscription_id uuid,
  p_from            date,
  p_to              date
)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $fn$
declare
  v_sub      public.subscriptions%rowtype;
  v_plan     public.subscription_plans%rowtype;
  v_date     date;
  v_dow      smallint;
  v_window   uuid;
  v_delivery_id uuid;
  v_created  integer := 0;
  v_meal     record;
  v_cost     integer;
  v_paused   boolean;
begin
  select * into v_sub from public.subscriptions where id = p_subscription_id;
  if not found then
    raise exception 'subscription % not found', p_subscription_id using errcode = 'no_data_found';
  end if;

  select * into v_plan from public.subscription_plans where id = v_sub.plan_id;

  -- Credit plans have no fixed calendar: the customer schedules against their
  -- balance instead (see schedule_credit_delivery).
  if v_plan.plan_type = 'meal_credits' then
    return 0;
  end if;

  if v_sub.status not in ('active','paused','past_due') then
    return 0;
  end if;

  v_date := p_from;
  while v_date <= p_to loop
    v_dow := extract(dow from v_date)::smallint;

    -- Honour the subscription's delivery days; empty means every day.
    if array_length(v_sub.delivery_days, 1) is null
       or v_dow = any(v_sub.delivery_days) then

      -- Skip days covered by an active pause.
      select exists (
        select 1 from public.subscription_pauses p
         where p.subscription_id = v_sub.id
           and p.cancelled_at is null
           and v_date between p.starts_on and p.ends_on
      ) into v_paused;

      if not v_paused then
        for v_meal in
          -- customer_selected plans deliver the customer's picks; the others
          -- deliver what the plan defines.
          select m.product_id, m.quantity,
                 coalesce(m.delivery_window_id, v_sub.delivery_window_id) as window_id
            from public.subscription_selected_meals m
           where v_plan.plan_type = 'customer_selected'
             and m.subscription_id = v_sub.id
             and (m.day_of_week is null or m.day_of_week = v_dow)
          union all
          select m.product_id, m.quantity,
                 coalesce(m.delivery_window_id, v_sub.delivery_window_id) as window_id
            from public.subscription_plan_meals m
           where v_plan.plan_type <> 'customer_selected'
             and m.plan_id = v_plan.id
             and not m.is_selectable
             and (m.day_of_week is null or m.day_of_week = v_dow)
        loop
          v_window := coalesce(v_meal.window_id, v_sub.delivery_window_id);
          exit when v_window is null;

          insert into public.subscription_deliveries
            (subscription_id, customer_id, scheduled_date, delivery_window_id,
             address_id, delivery_instructions, credits_cost)
          values
            (v_sub.id, v_sub.customer_id, v_date, v_window,
             v_sub.delivery_address_id, v_sub.delivery_instructions, 0)
          on conflict (subscription_id, scheduled_date, delivery_window_id) do nothing
          returning id into v_delivery_id;

          if v_delivery_id is null then
            select id into v_delivery_id from public.subscription_deliveries
             where subscription_id = v_sub.id
               and scheduled_date = v_date
               and delivery_window_id = v_window;
          else
            v_created := v_created + 1;
          end if;

          -- Credit cost follows the product, so a premium meal really does
          -- cost more than a standard one.
          select p.credit_cost * v_meal.quantity into v_cost
            from public.products p where p.id = v_meal.product_id;

          insert into public.subscription_delivery_items
            (delivery_id, product_id, quantity, credits_cost)
          select v_delivery_id, v_meal.product_id, v_meal.quantity, coalesce(v_cost, 0)
          where not exists (
            select 1 from public.subscription_delivery_items i
             where i.delivery_id = v_delivery_id and i.product_id = v_meal.product_id
          );

          update public.subscription_deliveries d
             set credits_cost = (
               select coalesce(sum(i.credits_cost), 0)
                 from public.subscription_delivery_items i
                where i.delivery_id = d.id)
           where d.id = v_delivery_id;

          v_delivery_id := null;
        end loop;
      end if;
    end if;

    v_date := v_date + 1;
  end loop;

  return v_created;
end;
$fn$;

-- -----------------------------------------------------------------------------
-- Credit plans: the customer books a delivery against their balance. The
-- balance is checked here, on the server, against the ledger.
-- -----------------------------------------------------------------------------
create or replace function public.schedule_credit_delivery(
  p_subscription_id  uuid,
  p_date             date,
  p_delivery_window_id uuid,
  p_items            jsonb,          -- [{product_id, quantity}]
  p_address_id       uuid default null
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $fn$
declare
  v_sub       public.subscriptions%rowtype;
  v_item      jsonb;
  v_cost      integer := 0;
  v_line      integer;
  v_balance   integer;
  v_delivery_id uuid;
begin
  perform app.assert_subscription_access(p_subscription_id);

  select * into v_sub from public.subscriptions where id = p_subscription_id for update;
  if not found then
    raise exception 'subscription % not found', p_subscription_id using errcode = 'no_data_found';
  end if;

  if v_sub.status <> 'active' then
    raise exception 'subscription is % and cannot schedule deliveries', v_sub.status
      using errcode = 'check_violation';
  end if;

  if p_date < app.business_date() then
    raise exception 'cannot schedule a delivery in the past' using errcode = 'check_violation';
  end if;

  for v_item in select * from jsonb_array_elements(p_items) loop
    if not app.product_is_orderable((v_item ->> 'product_id')::uuid) then
      raise exception 'one of the selected meals is currently unavailable'
        using errcode = 'check_violation';
    end if;

    select p.credit_cost * coalesce((v_item ->> 'quantity')::integer, 1)
      into v_line
      from public.products p where p.id = (v_item ->> 'product_id')::uuid;

    v_cost := v_cost + coalesce(v_line, 0);
  end loop;

  v_balance := public.subscription_credit_balance(p_subscription_id);
  if v_balance < v_cost then
    raise exception 'not enough credits: % available, % required', v_balance, v_cost
      using errcode = 'check_violation';
  end if;

  insert into public.subscription_deliveries
    (subscription_id, customer_id, scheduled_date, delivery_window_id,
     address_id, credits_cost)
  values
    (p_subscription_id, v_sub.customer_id, p_date, p_delivery_window_id,
     coalesce(p_address_id, v_sub.delivery_address_id), v_cost)
  returning id into v_delivery_id;

  for v_item in select * from jsonb_array_elements(p_items) loop
    insert into public.subscription_delivery_items
      (delivery_id, product_id, quantity, credits_cost)
    select v_delivery_id,
           (v_item ->> 'product_id')::uuid,
           coalesce((v_item ->> 'quantity')::integer, 1),
           p.credit_cost * coalesce((v_item ->> 'quantity')::integer, 1)
      from public.products p where p.id = (v_item ->> 'product_id')::uuid;
  end loop;

  return jsonb_build_object(
    'delivery_id', v_delivery_id,
    'credits_cost', v_cost,
    'credits_remaining', v_balance - v_cost);
end;
$fn$;


-- >>> 0013_kot_operations.sql =====================================

-- =============================================================================
-- 0013  Releasing deliveries to the KOT, and the operational actions on a
--       ticket (PRD 9, PRD 10)
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Ticket creation. Allocates the daily source-prefixed number, sets the base
-- priority and the SLA deadline. Never called for an unconfirmed order -- the
-- trigger from 0008 enforces that independently.
-- -----------------------------------------------------------------------------
create or replace function app.create_kot_ticket(p_order_id uuid)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $fn$
declare
  v_order   public.orders%rowtype;
  v_seq     integer;
  v_ticket  uuid;
  v_date    date;
begin
  select * into v_order from public.orders where id = p_order_id;
  if not found then
    raise exception 'order % not found', p_order_id using errcode = 'no_data_found';
  end if;

  -- One ticket per order, always.
  select id into v_ticket from public.kot_tickets where order_id = p_order_id;
  if v_ticket is not null then
    return v_ticket;
  end if;

  v_date := coalesce(v_order.business_date, app.business_date());
  v_seq  := app.next_kot_daily_number(v_order.source, v_date);

  insert into public.kot_tickets (
    order_id, source, business_date, daily_number, ticket_code,
    status, priority, sla_due_at, prep_eta_minutes, prep_eta_minutes_original
  ) values (
    p_order_id, v_order.source, v_date, v_seq,
    v_order.source::text || '-' || lpad(v_seq::text, 3, '0'),
    'NEW',
    app.base_priority(v_order.source),
    app.sla_due_at(v_order.source, coalesce(v_order.scheduled_for, now())),
    app.setting_int('kot.default_prep_minutes'),
    app.setting_int('kot.default_prep_minutes')
  )
  returning id into v_ticket;

  return v_ticket;
end;
$fn$;

-- =============================================================================
-- release_due_deliveries
-- =============================================================================
-- Turns scheduled subscription deliveries into real orders and tickets once
-- they fall inside the configurable release lead time (PRD 7, PRD 9).
-- Safe to run repeatedly and concurrently: rows are locked with SKIP LOCKED
-- and a released delivery is never picked up twice.
-- =============================================================================
create or replace function public.release_due_deliveries(
  p_now   timestamptz default now(),
  p_limit integer default 200
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $fn$
declare
  v_lead     integer := app.setting_int('kot.release_lead_time_minutes');
  v_rec      record;
  v_order_id uuid;
  v_ticket   uuid;
  v_balance  integer;
  v_released integer := 0;
  v_blocked  integer := 0;
  v_results  jsonb := '[]'::jsonb;
  v_cost     numeric(12,2);
begin
  for v_rec in
    select d.*, w.starts_at, s.status as sub_status, s.customer_id as sub_customer
      from public.subscription_deliveries d
      join public.delivery_windows w on w.id = d.delivery_window_id
      join public.subscriptions s     on s.id = d.subscription_id
     where d.status = 'scheduled'
       and s.status = 'active'
       -- Due when the window opens within the lead time.
       and ((d.scheduled_date + w.starts_at) at time zone app.business_timezone())
             - make_interval(mins => v_lead) <= p_now
     order by d.scheduled_date, w.starts_at
     limit p_limit
     for update of d skip locked
  loop
    -- Entitlement check against the ledger, not a cached balance.
    v_balance := public.subscription_credit_balance(v_rec.subscription_id);

    if v_rec.credits_cost > 0 and v_balance < v_rec.credits_cost then
      v_blocked := v_blocked + 1;
      perform public.record_audit_event(
        'state_transition', 'subscription_deliveries', v_rec.id::text, null,
        jsonb_build_object('blocked', 'insufficient_credits',
                           'required', v_rec.credits_cost, 'available', v_balance));
      continue;
    end if;

    -- A subscription delivery is fulfilment of an already-paid plan, so the
    -- order itself carries no charge. Revenue is attributed to the
    -- subscription payment; double-counting it here would inflate analytics.
    insert into public.orders (
      source, status, customer_id, subscription_id, subscription_delivery_id,
      business_date, scheduled_for, delivery_window_id,
      customer_name_snapshot, customer_phone_snapshot, address_snapshot,
      delivery_instructions,
      subtotal, discount_total, delivery_fee, tax_total, grand_total,
      idempotency_key
    )
    select
      -- Explicit casts: INSERT ... SELECT does not coerce bare literals to the
      -- target column's enum type the way INSERT ... VALUES does.
      'SX'::public.order_source, 'CONFIRMED'::public.order_status,
      v_rec.customer_id, v_rec.subscription_id, v_rec.id,
      v_rec.scheduled_date,
      (v_rec.scheduled_date + v_rec.starts_at) at time zone app.business_timezone(),
      v_rec.delivery_window_id,
      c.full_name, c.phone,
      to_jsonb(a.*) - 'created_at' - 'updated_at',
      coalesce(v_rec.delivery_instructions, a.delivery_instructions),
      0, 0, 0, 0, 0,
      'delivery:' || v_rec.id::text
      from public.customers c
      left join public.customer_addresses a
        on a.id = coalesce(v_rec.address_id,
                          (select delivery_address_id from public.subscriptions
                            where id = v_rec.subscription_id))
     where c.id = v_rec.customer_id
    on conflict (idempotency_key) where idempotency_key is not null do nothing
    returning id into v_order_id;

    if v_order_id is null then
      select id into v_order_id from public.orders
       where idempotency_key = 'delivery:' || v_rec.id::text;
    end if;

    -- Line items, snapshotted so later catalog edits cannot rewrite the ticket.
    insert into public.order_items (
      order_id, product_id, name_snapshot, quantity, unit_price, line_subtotal,
      variants_snapshot, add_ons_snapshot, credits_consumed, estimated_cost,
      special_instructions
    )
    select
      v_order_id, p.id, p.name, i.quantity, 0, 0,
      coalesce((
        select jsonb_agg(jsonb_build_object('group', vg.name, 'name', v.name,
                                            'price_delta', v.price_delta))
          from public.variants v
          join public.variant_groups vg on vg.id = v.variant_group_id
         where v.id = any(i.variant_ids)), '[]'::jsonb),
      coalesce((
        select jsonb_agg(jsonb_build_object('name', ao.name, 'price', ao.price))
          from public.add_ons ao where ao.id = any(i.add_on_ids)), '[]'::jsonb),
      i.credits_cost,
      coalesce(p.estimated_cost, 0) * i.quantity,
      i.special_instructions
      from public.subscription_delivery_items i
      join public.products p on p.id = i.product_id
     where i.delivery_id = v_rec.id
       and not exists (select 1 from public.order_items oi where oi.order_id = v_order_id);

    select coalesce(sum(estimated_cost), 0) into v_cost
      from public.order_items where order_id = v_order_id;

    update public.orders set estimated_food_cost = v_cost where id = v_order_id;

    -- Consume credits. The idempotency key ties the entry to this delivery, so
    -- a re-run cannot debit twice.
    if v_rec.credits_cost > 0 then
      insert into public.subscription_credit_ledger
        (subscription_id, entry_type, credits, reason, delivery_id, idempotency_key)
      values
        (v_rec.subscription_id, 'consume', -v_rec.credits_cost,
         'Delivery released to kitchen', v_rec.id,
         'consume:' || v_rec.id::text)
      on conflict (subscription_id, idempotency_key) do nothing;
    end if;

    v_ticket := app.create_kot_ticket(v_order_id);

    update public.subscription_deliveries
       set status = 'released', released_at = now(), order_id = v_order_id
     where id = v_rec.id;

    v_released := v_released + 1;
    v_results := v_results || jsonb_build_object(
      'delivery_id', v_rec.id, 'order_id', v_order_id, 'ticket_id', v_ticket);
  end loop;

  return jsonb_build_object(
    'released', v_released,
    'blocked_insufficient_credits', v_blocked,
    'lead_time_minutes', v_lead,
    'details', v_results);
end;
$fn$;

-- =============================================================================
-- Operational actions on a ticket
-- =============================================================================
-- All of them go through the same door. The trigger in 0007 decides whether
-- the transition is legal and whether this actor may make it, so no caller can
-- reach an unauthorised state by writing the column directly.
-- =============================================================================
create or replace function public.transition_kot_ticket(
  p_ticket_id uuid,
  p_to_status public.kot_status,
  p_reason    text default null,
  p_notes     text default null
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $fn$
declare
  v_ticket public.kot_tickets%rowtype;
  v_from   public.kot_status;
begin
  select * into v_ticket from public.kot_tickets where id = p_ticket_id for update;
  if not found then
    raise exception 'ticket % not found', p_ticket_id using errcode = 'no_data_found';
  end if;

  -- Replaying the same transition is a no-op rather than an error: a double
  -- tap on a tablet under rush conditions should not surface a failure.
  if v_ticket.status = p_to_status then
    return jsonb_build_object('ticket_id', p_ticket_id, 'status', p_to_status, 'noop', true);
  end if;

  v_from := v_ticket.status;

  update public.kot_tickets
     set status = p_to_status,
         rejection_reason = case when p_to_status = 'REJECTED' then p_reason else rejection_reason end,
         cancellation_reason = case when p_to_status = 'CANCELLED' then p_reason else cancellation_reason end,
         notes = coalesce(p_notes, notes)
   where id = p_ticket_id;

  -- Keep the order's own machine in step without letting either one own the
  -- other's columns.
  if p_to_status = 'PREPARING' then
    update public.orders set status = 'IN_PROGRESS'
     where id = v_ticket.order_id and status = 'CONFIRMED';
  elsif p_to_status = 'COMPLETED' then
    update public.orders set status = 'COMPLETED' where id = v_ticket.order_id;
    update public.subscription_deliveries
       set status = 'fulfilled', fulfilled_at = now()
     where order_id = v_ticket.order_id;
  elsif p_to_status in ('REJECTED','CANCELLED') then
    update public.orders
       set status = case when p_to_status = 'REJECTED'
                         then 'REJECTED'::public.order_status
                         else 'CANCELLED'::public.order_status end,
           cancellation_reason = p_reason
     where id = v_ticket.order_id;
  end if;

  return jsonb_build_object(
    'ticket_id', p_ticket_id,
    'from', v_from,
    'status', p_to_status,
    'noop', false);
end;
$fn$;

-- Manager-only ETA override (PRD 9). The original estimate is preserved so the
-- override is visible in history rather than overwriting the kitchen's number.
create or replace function public.override_prep_eta(
  p_ticket_id uuid,
  p_minutes   integer
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $fn$
begin
  if not app.has_permission('kot.override_eta') then
    raise exception 'not permitted to override preparation ETA'
      using errcode = 'insufficient_privilege';
  end if;

  if p_minutes is null or p_minutes <= 0 then
    raise exception 'ETA must be a positive number of minutes'
      using errcode = 'invalid_parameter_value';
  end if;

  update public.kot_tickets
     set prep_eta_minutes = p_minutes,
         eta_overridden_by = app.current_actor_id(),
         eta_overridden_at = now()
   where id = p_ticket_id;

  if not found then
    raise exception 'ticket % not found', p_ticket_id using errcode = 'no_data_found';
  end if;

  perform public.record_audit_event(
    'update', 'kot_tickets', p_ticket_id::text, null,
    jsonb_build_object('prep_eta_minutes', p_minutes));

  return jsonb_build_object('ticket_id', p_ticket_id, 'prep_eta_minutes', p_minutes);
end;
$fn$;

-- =============================================================================
-- Skip, pause and cancel (PRD 7)
-- =============================================================================
-- Skipping returns the entitlement by default; the rule is a setting, and the
-- return is a compensating ledger entry rather than an edit to the debit.
-- =============================================================================
create or replace function public.skip_subscription_delivery(
  p_delivery_id uuid,
  p_reason      text default null
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $fn$
declare
  v_delivery public.subscription_deliveries%rowtype;
  v_plan     public.subscription_plans%rowtype;
  v_returns  boolean;
  v_returned integer := 0;
begin
  select * into v_delivery from public.subscription_deliveries
   where id = p_delivery_id for update;

  if not found then
    raise exception 'delivery % not found', p_delivery_id using errcode = 'no_data_found';
  end if;

  perform app.assert_subscription_access(v_delivery.subscription_id);

  if v_delivery.status = 'skipped' then
    return jsonb_build_object('delivery_id', p_delivery_id, 'status', 'skipped', 'noop', true);
  end if;

  -- Once a ticket exists the kitchen may already be cooking; skipping then is
  -- an operational decision, not a customer self-service one.
  if v_delivery.status <> 'scheduled' then
    raise exception 'delivery is % and can no longer be skipped', v_delivery.status
      using errcode = 'check_violation';
  end if;

  select p.* into v_plan
    from public.subscription_plans p
    join public.subscriptions s on s.plan_id = p.id
   where s.id = v_delivery.subscription_id;

  v_returns := coalesce(v_plan.skip_returns_credit,
                        app.setting_bool('subscription.skip_returns_credit'));

  update public.subscription_deliveries
     set status = 'skipped',
         skipped_at = now(),
         skip_reason = p_reason,
         skipped_by = app.current_actor_id()
   where id = p_delivery_id;

  if v_returns and v_delivery.credits_cost > 0 then
    insert into public.subscription_credit_ledger
      (subscription_id, entry_type, credits, reason, delivery_id, idempotency_key, created_by)
    values
      (v_delivery.subscription_id, 'reverse', v_delivery.credits_cost,
       'Skipped delivery', p_delivery_id,
       'reverse-skip:' || p_delivery_id::text, app.current_actor_id())
    on conflict (subscription_id, idempotency_key) do nothing;

    v_returned := v_delivery.credits_cost;
  end if;

  return jsonb_build_object(
    'delivery_id', p_delivery_id,
    'status', 'skipped',
    'credits_returned', v_returned,
    'credits_remaining', public.subscription_credit_balance(v_delivery.subscription_id));
end;
$fn$;

create or replace function public.pause_subscription(
  p_subscription_id uuid,
  p_starts_on       date,
  p_ends_on         date,
  p_reason          text default null
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $fn$
declare
  v_sub        public.subscriptions%rowtype;
  v_plan       public.subscription_plans%rowtype;
  v_max_pauses integer;
  v_max_days   integer;
  v_used       integer;
  v_days       integer;
  v_pause_id   uuid;
begin
  perform app.assert_subscription_access(p_subscription_id);

  select * into v_sub from public.subscriptions where id = p_subscription_id for update;
  if not found then
    raise exception 'subscription % not found', p_subscription_id using errcode = 'no_data_found';
  end if;

  if v_sub.status not in ('active','past_due') then
    raise exception 'subscription is % and cannot be paused', v_sub.status
      using errcode = 'check_violation';
  end if;

  if p_ends_on < p_starts_on then
    raise exception 'pause end date is before its start date' using errcode = 'check_violation';
  end if;

  if p_starts_on < app.business_date() then
    raise exception 'a pause cannot start in the past' using errcode = 'check_violation';
  end if;

  select * into v_plan from public.subscription_plans where id = v_sub.plan_id;

  -- Both limits are configurable and still pending owner sign-off (PRD 22);
  -- nothing here hardcodes "2 pauses" or "3-5 days".
  v_max_pauses := coalesce(v_plan.max_pauses_per_period,
                           app.setting_int('subscription.max_pauses_per_period'));
  v_max_days   := coalesce(v_plan.max_pause_days,
                           app.setting_int('subscription.max_pause_days'));

  v_days := (p_ends_on - p_starts_on) + 1;
  if v_days > v_max_days then
    raise exception 'a pause may not exceed % days', v_max_days using errcode = 'check_violation';
  end if;

  select count(*) into v_used
    from public.subscription_pauses
   where subscription_id = p_subscription_id
     and cancelled_at is null
     and starts_on >= coalesce(v_sub.current_period_start, v_sub.starts_on);

  if v_used >= v_max_pauses then
    raise exception 'pause limit reached for this period (% allowed)', v_max_pauses
      using errcode = 'check_violation';
  end if;

  insert into public.subscription_pauses
    (subscription_id, starts_on, ends_on, reason, created_by)
  values
    (p_subscription_id, p_starts_on, p_ends_on, p_reason, app.current_actor_id())
  returning id into v_pause_id;

  update public.subscriptions
     set status = case when p_starts_on <= app.business_date() then 'paused' else status end,
         paused_until = p_ends_on,
         pauses_used_this_period = v_used + 1
   where id = p_subscription_id;

  -- Deliveries inside the pause window are skipped, returning entitlement by
  -- the same rule as a manual skip.
  perform public.skip_subscription_delivery(d.id, 'Subscription paused')
     from public.subscription_deliveries d
    where d.subscription_id = p_subscription_id
      and d.status = 'scheduled'
      and d.scheduled_date between p_starts_on and p_ends_on;

  return jsonb_build_object(
    'pause_id', v_pause_id,
    'starts_on', p_starts_on,
    'ends_on', p_ends_on,
    'pauses_used', v_used + 1,
    'pauses_allowed', v_max_pauses);
end;
$fn$;

-- Cancellation stops future deliveries but preserves the historical and
-- current-period record (PRD 7). Refund handling is a separate, pending policy.
create or replace function public.cancel_subscription(
  p_subscription_id uuid,
  p_reason          text default null
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $fn$
declare
  v_sub       public.subscriptions%rowtype;
  v_cancelled integer;
begin
  perform app.assert_subscription_access(p_subscription_id);

  select * into v_sub from public.subscriptions where id = p_subscription_id for update;
  if not found then
    raise exception 'subscription % not found', p_subscription_id using errcode = 'no_data_found';
  end if;

  if v_sub.status = 'cancelled' then
    return jsonb_build_object('subscription_id', p_subscription_id, 'status', 'cancelled', 'noop', true);
  end if;

  update public.subscriptions
     set status = 'cancelled',
         cancelled_at = now(),
         cancellation_reason = p_reason,
         cancelled_by = app.current_actor_id(),
         next_renewal_at = null
   where id = p_subscription_id;

  -- Only future, not-yet-released deliveries are withdrawn; anything already
  -- in the kitchen stays in the kitchen.
  with cancelled as (
    update public.subscription_deliveries
       set status = 'cancelled', cancelled_at = now()
     where subscription_id = p_subscription_id
       and status = 'scheduled'
    returning 1)
  select count(*) into v_cancelled from cancelled;

  return jsonb_build_object(
    'subscription_id', p_subscription_id,
    'status', 'cancelled',
    'future_deliveries_cancelled', v_cancelled,
    'credits_remaining', public.subscription_credit_balance(p_subscription_id));
end;
$fn$;


-- >>> 0014_marketplace_ingestion.sql ==============================

-- =============================================================================
-- 0014  Marketplace ingestion, status sync and failure isolation (PRD 16)
-- =============================================================================
-- Swiggy and Zomato are order channels, not separate systems. Everything they
-- send lands in the same orders/kot_tickets tables as a website subscription
-- delivery; only the source prefix and the priority differ.
--
-- Nothing here calls a marketplace API. The adapters in the application layer
-- do that, and only for capabilities recorded as 'integrated' in
-- integration_capabilities. This file is the ingestion boundary.
-- =============================================================================

create or replace function app.provider_to_source(p_provider public.integration_provider)
returns public.order_source
language sql
immutable
as $fn$
  select case p_provider when 'swiggy' then 'SW'::public.order_source
                         when 'zomato' then 'ZM'::public.order_source end;
$fn$;

-- -----------------------------------------------------------------------------
-- Circuit breaker. One marketplace failing must never stop the others
-- (PRD 16), so health is tracked per account and read before any outbound call.
-- -----------------------------------------------------------------------------
create or replace function public.record_integration_failure(
  p_provider public.integration_provider,
  p_error    text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $fn$
declare
  v_threshold integer := coalesce(app.setting_int('integration.failure_threshold'), 5);
  v_cooldown  integer := coalesce(app.setting_int('integration.circuit_cooldown_minutes'), 10);
  v_acct      public.integration_accounts%rowtype;
begin
  update public.integration_accounts
     set consecutive_failures = consecutive_failures + 1,
         last_error = p_error,
         last_error_at = now(),
         health = case
           when consecutive_failures + 1 >= v_threshold then 'down'::public.integration_health
           else 'degraded'::public.integration_health end,
         circuit_open_until = case
           when consecutive_failures + 1 >= v_threshold
           then now() + make_interval(mins => v_cooldown)
           else circuit_open_until end
   where provider = p_provider
  returning * into v_acct;

  return jsonb_build_object(
    'provider', p_provider,
    'health', v_acct.health,
    'consecutive_failures', v_acct.consecutive_failures,
    'circuit_open_until', v_acct.circuit_open_until);
end;
$fn$;

create or replace function public.record_integration_success(
  p_provider public.integration_provider
)
returns void
language sql
volatile
security definer
set search_path = ''
as $fn$
  update public.integration_accounts
     set consecutive_failures = 0,
         health = case when is_enabled then 'connected'::public.integration_health
                       else 'disabled'::public.integration_health end,
         last_healthy_at = now(),
         circuit_open_until = null,
         last_error = null
   where provider = p_provider;
$fn$;

-- =============================================================================
-- ingest_marketplace_order
-- =============================================================================
-- Idempotent on (source, external_order_id): a replayed webhook returns the
-- existing order instead of creating a second ticket.
--
-- Marketplace orders are settled by the marketplace, so no payment row is
-- created here; their revenue is attributed from the order totals the platform
-- reports, and reconciled against the platform later.
-- =============================================================================
create or replace function public.ingest_marketplace_order(
  p_provider          public.integration_provider,
  p_external_order_id text,
  p_items             jsonb,              -- [{name, quantity, unit_price, variants, add_ons, instructions, product_id?}]
  p_totals            jsonb default '{}'::jsonb,
  p_customer          jsonb default '{}'::jsonb,
  p_payload           jsonb default '{}'::jsonb,
  p_external_event_id text default null,
  p_placed_at         timestamptz default now()
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $fn$
declare
  v_source   public.order_source := app.provider_to_source(p_provider);
  v_order_id uuid;
  v_ticket   uuid;
  v_item     jsonb;
  v_existing uuid;
  v_subtotal numeric(12,2) := 0;
  v_cost     numeric(12,2) := 0;
  v_account  uuid;
begin
  if v_source is null then
    raise exception 'unknown marketplace provider %', p_provider
      using errcode = 'invalid_parameter_value';
  end if;

  select id into v_account from public.integration_accounts where provider = p_provider;

  -- Duplicate webhook: recorded, then ignored.
  if p_external_event_id is not null then
    insert into public.integration_events
      (provider, account_id, direction, event_type, external_event_id,
       external_order_id, payload, signature_valid, status)
    values
      (p_provider, v_account, 'inbound', 'order.received', p_external_event_id,
       p_external_order_id, p_payload, true, 'received')
    on conflict (provider, external_event_id) where external_event_id is not null do nothing;

    if not found then
      select o.id into v_existing from public.orders o
       where o.source = v_source and o.external_order_id = p_external_order_id;

      return jsonb_build_object(
        'duplicate', true, 'order_id', v_existing, 'external_order_id', p_external_order_id);
    end if;
  end if;

  -- Duplicate order id, arriving without an event id.
  select o.id into v_existing from public.orders o
   where o.source = v_source and o.external_order_id = p_external_order_id;

  if v_existing is not null then
    select id into v_ticket from public.kot_tickets where order_id = v_existing;
    return jsonb_build_object(
      'duplicate', true, 'order_id', v_existing, 'ticket_id', v_ticket);
  end if;

  insert into public.orders (
    source, status, external_order_id, external_status, external_payload,
    placed_at, business_date, scheduled_for,
    customer_name_snapshot, customer_phone_snapshot, address_snapshot,
    delivery_instructions, special_instructions,
    subtotal, discount_total, delivery_fee, tax_total, grand_total
  ) values (
    v_source, 'CONFIRMED', p_external_order_id,
    coalesce(p_payload ->> 'status', 'placed'), p_payload,
    p_placed_at, app.business_date(p_placed_at), p_placed_at,
    nullif(p_customer ->> 'name', ''),
    nullif(p_customer ->> 'phone', ''),
    case when p_customer ? 'address' then p_customer -> 'address' end,
    nullif(p_customer ->> 'delivery_instructions', ''),
    nullif(p_payload ->> 'special_instructions', ''),
    coalesce((p_totals ->> 'subtotal')::numeric, 0),
    coalesce((p_totals ->> 'discount_total')::numeric, 0),
    coalesce((p_totals ->> 'delivery_fee')::numeric, 0),
    coalesce((p_totals ->> 'tax_total')::numeric, 0),
    coalesce((p_totals ->> 'grand_total')::numeric, 0)
  )
  returning id into v_order_id;

  for v_item in select * from jsonb_array_elements(p_items) loop
    insert into public.order_items (
      order_id, product_id, name_snapshot, quantity, unit_price, line_subtotal,
      variants_snapshot, add_ons_snapshot, estimated_cost, special_instructions
    )
    select
      v_order_id,
      nullif(v_item ->> 'product_id', '')::uuid,
      v_item ->> 'name',
      coalesce((v_item ->> 'quantity')::integer, 1),
      coalesce((v_item ->> 'unit_price')::numeric, 0),
      coalesce((v_item ->> 'unit_price')::numeric, 0) * coalesce((v_item ->> 'quantity')::integer, 1),
      coalesce(v_item -> 'variants', '[]'::jsonb),
      coalesce(v_item -> 'add_ons', '[]'::jsonb),
      -- Estimated cost falls back to the channel's default food-cost percent
      -- when the item is not mapped to one of our products.
      coalesce(
        (select p.estimated_cost * coalesce((v_item ->> 'quantity')::integer, 1)
           from public.products p where p.id = nullif(v_item ->> 'product_id', '')::uuid),
        coalesce((v_item ->> 'unit_price')::numeric, 0)
          * coalesce((v_item ->> 'quantity')::integer, 1)
          * coalesce((select default_food_cost_percent from public.cost_settings
                       where is_active and (source = v_source or source is null)
                       order by (source is not null) desc limit 1), 0) / 100.0),
      nullif(v_item ->> 'instructions', '');
  end loop;

  select coalesce(sum(line_subtotal), 0), coalesce(sum(estimated_cost), 0)
    into v_subtotal, v_cost
    from public.order_items where order_id = v_order_id;

  -- Trust the platform's own totals when it sends them; fall back to the sum
  -- of the lines when it does not.
  update public.orders
     set subtotal = case when subtotal = 0 then v_subtotal else subtotal end,
         grand_total = case when grand_total = 0 then v_subtotal else grand_total end,
         estimated_food_cost = v_cost
   where id = v_order_id;

  v_ticket := app.create_kot_ticket(v_order_id);

  if p_external_event_id is not null then
    update public.integration_events
       set status = 'processed', processed_at = now(), order_id = v_order_id
     where provider = p_provider and external_event_id = p_external_event_id;
  end if;

  perform public.record_integration_success(p_provider);

  return jsonb_build_object(
    'duplicate', false,
    'order_id', v_order_id,
    'ticket_id', v_ticket,
    'source', v_source,
    'external_order_id', p_external_order_id);
end;
$fn$;

-- -----------------------------------------------------------------------------
-- Status coming back from the marketplace. Cancellation rules follow the
-- marketplace (PRD 9), so a platform cancellation cancels our ticket even
-- mid-preparation -- and says so in the history.
-- -----------------------------------------------------------------------------
create or replace function public.sync_marketplace_order_status(
  p_provider          public.integration_provider,
  p_external_order_id text,
  p_external_status   text,
  p_external_event_id text default null,
  p_payload           jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $fn$
declare
  v_source public.order_source := app.provider_to_source(p_provider);
  v_order  public.orders%rowtype;
  v_ticket public.kot_tickets%rowtype;
  v_account uuid;
  v_applied text := 'noted';
begin
  select id into v_account from public.integration_accounts where provider = p_provider;

  if p_external_event_id is not null then
    insert into public.integration_events
      (provider, account_id, direction, event_type, external_event_id,
       external_order_id, payload, signature_valid, status)
    values
      (p_provider, v_account, 'inbound', 'order.status', p_external_event_id,
       p_external_order_id, p_payload, true, 'received')
    on conflict (provider, external_event_id) where external_event_id is not null do nothing;

    if not found then
      return jsonb_build_object('duplicate', true, 'external_order_id', p_external_order_id);
    end if;
  end if;

  select * into v_order from public.orders
   where source = v_source and external_order_id = p_external_order_id;

  if not found then
    -- A status for an order we never ingested is a real discrepancy, not
    -- something to invent an order for.
    update public.integration_events
       set status = 'failed', error = 'no matching internal order', processed_at = now()
     where provider = p_provider and external_event_id = p_external_event_id;

    return jsonb_build_object('matched', false, 'external_order_id', p_external_order_id);
  end if;

  update public.orders set external_status = p_external_status where id = v_order.id;

  select * into v_ticket from public.kot_tickets where order_id = v_order.id;

  if lower(p_external_status) in ('cancelled','canceled','rejected')
     and v_ticket.id is not null
     and v_ticket.status not in ('COMPLETED','CANCELLED','REJECTED') then

    update public.kot_tickets
       set cancellation_origin = 'marketplace'
     where id = v_ticket.id;

    perform public.transition_kot_ticket(
      v_ticket.id, 'CANCELLED',
      format('Cancelled by %s', p_provider));

    v_applied := 'cancelled';
  end if;

  if p_external_event_id is not null then
    update public.integration_events
       set status = 'processed', processed_at = now(), order_id = v_order.id
     where provider = p_provider and external_event_id = p_external_event_id;
  end if;

  return jsonb_build_object(
    'matched', true,
    'order_id', v_order.id,
    'ticket_id', v_ticket.id,
    'external_status', p_external_status,
    'applied', v_applied);
end;
$fn$;

-- -----------------------------------------------------------------------------
-- Two-way reconciliation (PRD 16). Compares a batch of external order ids for
-- a window against what we hold and records the differences; it never quietly
-- creates or deletes anything.
-- -----------------------------------------------------------------------------
create or replace function public.reconcile_marketplace_orders(
  p_provider     public.integration_provider,
  p_window_start timestamptz,
  p_window_end   timestamptz,
  p_external_ids text[]
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $fn$
declare
  v_source           public.order_source := app.provider_to_source(p_provider);
  v_missing_internal jsonb;
  v_missing_external jsonb;
  v_internal_count   integer;
  v_status           text;
  v_run_id           uuid;
begin
  select coalesce(jsonb_agg(x.id), '[]'::jsonb) into v_missing_internal
    from unnest(p_external_ids) as x(id)
   where not exists (
     select 1 from public.orders o
      where o.source = v_source and o.external_order_id = x.id);

  -- Held here but not reported by the platform for this window.
  select coalesce(jsonb_agg(o.external_order_id), '[]'::jsonb)
    into v_missing_external
    from public.orders o
   where o.source = v_source
     and o.placed_at >= p_window_start
     and o.placed_at <  p_window_end
     and not (o.external_order_id = any(p_external_ids));

  select count(*) into v_internal_count
    from public.orders o
   where o.source = v_source
     and o.placed_at >= p_window_start
     and o.placed_at <  p_window_end;

  v_status := case
    when jsonb_array_length(v_missing_internal) = 0
     and jsonb_array_length(v_missing_external) = 0 then 'clean'
    else 'discrepancies' end;

  insert into public.integration_reconciliation
    (provider, window_start, window_end, external_count, internal_count,
     missing_internal, missing_external, status)
  values
    (p_provider, p_window_start, p_window_end,
     coalesce(array_length(p_external_ids, 1), 0), v_internal_count,
     v_missing_internal, v_missing_external, v_status)
  returning id into v_run_id;

  return jsonb_build_object(
    'run_id', v_run_id,
    'status', v_status,
    'external_count', coalesce(array_length(p_external_ids, 1), 0),
    'internal_count', v_internal_count,
    'missing_internal', v_missing_internal,
    'missing_external', v_missing_external);
end;
$fn$;


-- >>> 0015_views_and_analytics.sql ================================

-- =============================================================================
-- 0015  Read surfaces: the KOT board, the kitchen display, and owner analytics
--       (PRD 9, 12, 17)
-- =============================================================================
-- Kitchen staff must not receive financial data. Rather than trusting each
-- caller to select the right columns, the money columns are masked in the view
-- itself: a reader without the permission gets nulls, whatever they ask for.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- v_kot_tickets: the one board every operational screen reads.
-- Manager and Owner see everything; Owner's write access is separately denied
-- by RLS, which is what makes their KOT read-only (PRD 9).
-- -----------------------------------------------------------------------------
create view public.v_kot_tickets as
select
  t.id,
  t.order_id,
  t.ticket_code,
  t.source,
  t.status,
  t.business_date,
  t.daily_number,
  t.priority,
  t.sla_due_at,
  -- Urgency escalates any ticket as its deadline approaches, regardless of
  -- the source's baseline priority (PRD 9).
  case
    when t.sla_due_at is null then 0
    when t.sla_due_at <= now() then 1000
    else greatest(0, 600 - extract(epoch from (t.sla_due_at - now()))::integer / 6)
  end as urgency_score,
  t.prep_eta_minutes,
  t.prep_eta_minutes_original,
  t.eta_overridden_at,
  t.accepted_at,
  t.preparing_at,
  t.ready_at,
  t.picked_up_at,
  t.out_for_delivery_at,
  t.delivered_at,
  t.completed_at,
  t.rejected_at,
  t.rejection_reason,
  t.cancelled_at,
  t.cancellation_reason,
  t.cancellation_origin,
  t.notes,
  t.created_at,

  o.order_number,
  o.external_order_id,
  o.scheduled_for,
  o.special_instructions,
  o.delivery_instructions,
  o.customer_name_snapshot as customer_name,
  -- Contact details are operational, but only for roles that need them.
  case when app.has_permission('orders.view_contact')
       then o.customer_phone_snapshot end as customer_phone,
  w.code  as delivery_window_code,
  w.label as delivery_window_label,
  w.starts_at as window_starts_at,
  w.ends_at   as window_ends_at,

  -- Financial columns, masked unless the reader is allowed them (PRD 17).
  case when app.has_permission('orders.view_financial') then o.grand_total end as order_total,
  case when app.has_permission('orders.view_financial') then o.subtotal    end as order_subtotal,

  s.subscription_number,
  (select count(*) from public.order_items oi where oi.order_id = o.id) as item_count
from public.kot_tickets t
join public.orders o on o.id = t.order_id
left join public.delivery_windows w on w.id = o.delivery_window_id
left join public.subscriptions s on s.id = o.subscription_id
where app.is_staff();

-- -----------------------------------------------------------------------------
-- v_kot_ticket_items: what the kitchen actually cooks. Prices are masked the
-- same way; the kitchen sees names, quantities, variants, add-ons and
-- instructions and nothing else (PRD 5.4, PRD 17).
-- -----------------------------------------------------------------------------
create view public.v_kot_ticket_items as
select
  i.id,
  t.id as ticket_id,
  i.order_id,
  i.product_id,
  i.name_snapshot as name,
  i.quantity,
  i.variants_snapshot as variants,
  i.add_ons_snapshot  as add_ons,
  i.special_instructions,
  case when app.has_permission('orders.view_financial') then i.unit_price   end as unit_price,
  case when app.has_permission('orders.view_financial') then i.line_subtotal end as line_subtotal
from public.order_items i
join public.kot_tickets t on t.order_id = i.order_id
where app.is_staff();

-- -----------------------------------------------------------------------------
-- v_customer_deliveries: the customer's own upcoming and past deliveries.
-- -----------------------------------------------------------------------------
create view public.v_customer_deliveries as
select
  d.id,
  d.subscription_id,
  d.customer_id,
  d.scheduled_date,
  d.status,
  d.credits_cost,
  d.skipped_at,
  d.skip_reason,
  w.code  as window_code,
  w.label as window_label,
  w.starts_at as window_starts_at,
  s.subscription_number,
  t.status      as kitchen_status,
  t.ticket_code,
  t.prep_eta_minutes,
  coalesce((
    select jsonb_agg(jsonb_build_object('name', p.name, 'quantity', i.quantity))
      from public.subscription_delivery_items i
      join public.products p on p.id = i.product_id
     where i.delivery_id = d.id), '[]'::jsonb) as items
from public.subscription_deliveries d
join public.subscriptions s on s.id = d.subscription_id
join public.delivery_windows w on w.id = d.delivery_window_id
left join public.kot_tickets t on t.order_id = d.order_id
where d.customer_id = app.current_customer_id()
   or app.has_permission('subscriptions.view_all');

-- =============================================================================
-- Analytics (PRD 12)
-- =============================================================================
-- Every metric derives from the timestamps and events the operational tables
-- already record, so the numbers reconcile with the audit history rather than
-- being accumulated separately.
-- =============================================================================

-- Per-order operational and financial facts.
create view public.v_analytics_orders as
select
  o.id as order_id,
  o.order_number,
  o.source,
  o.business_date,
  o.status,
  o.placed_at,
  o.completed_at,

  -- Website revenue is recognised on the subscription payment, not on each
  -- prepaid delivery, so subscription fulfilment orders contribute zero here
  -- and are not double counted.
  case when o.source = 'SX' then 0 else o.grand_total end as revenue,

  o.estimated_food_cost,

  -- Channel fees resolved from the configurable (initially dummy) assumptions.
  round(
    case when o.source = 'SX' then 0 else o.grand_total end
      * coalesce(cs.commission_percent, 0) / 100.0
    + case when o.source = 'SX' then 0 else o.grand_total end
      * coalesce(cs.payment_fee_percent, 0) / 100.0
    + case when o.source = 'SX' then 0 else coalesce(cs.payment_fee_fixed, 0) end
    + coalesce(cs.packaging_cost_per_order, 0)
  , 2) as channel_fees,

  -- Durations, in seconds, only where the timestamps really exist (PRD 10).
  extract(epoch from (t.ready_at    - t.accepted_at))::integer as prep_seconds,
  extract(epoch from (o.completed_at - o.created_at))::integer as order_seconds,
  extract(epoch from (t.picked_up_at - t.ready_at))::integer   as pickup_wait_seconds,
  extract(epoch from (t.delivered_at - t.picked_up_at))::integer as delivery_seconds,

  t.ticket_code,
  t.status as kot_status
from public.orders o
left join public.kot_tickets t on t.order_id = o.id
left join lateral (
  select * from public.cost_settings c
   where c.is_active
     and (c.source = o.source or c.source is null)
     and c.effective_from <= o.placed_at
     and (c.effective_to is null or c.effective_to > o.placed_at)
   order by (c.source is not null) desc, c.effective_from desc
   limit 1
) cs on true
where app.has_permission('analytics.view');

-- Revenue separated by source (PRD 12). Website revenue comes from verified
-- subscription payments; marketplace revenue from the platform order totals.
create view public.v_revenue_by_source as
select
  'SX'::public.order_source as source,
  'Website - Subscriptions'  as source_label,
  app.business_date(p.verified_at) as business_date,
  count(*)                   as transaction_count,
  sum(p.amount)              as revenue
from public.payments p
where p.status = 'success'
  and p.verified_at is not null
  and p.subscription_id is not null
  and app.has_permission('analytics.view')
group by 3

union all

select
  o.source,
  case o.source when 'SW' then 'Swiggy' when 'ZM' then 'Zomato' else 'Other' end,
  o.business_date,
  count(*),
  sum(o.grand_total)
from public.orders o
where o.source in ('SW','ZM')
  and o.status not in ('CANCELLED','REJECTED','DRAFT')
  and app.has_permission('analytics.view')
group by 1, 2, 3;

-- -----------------------------------------------------------------------------
-- Daily operational metrics by source.
--
-- Revenue and cost are deliberately taken from different places and joined
-- here. Subscription revenue is recognised when the payment is verified, while
-- the cost of a subscription meal lands on the fulfilment order days later. If
-- this view summed order totals alone, the website channel would show its
-- costs with none of its income and report a permanent loss.
-- -----------------------------------------------------------------------------
create view public.v_kot_metrics_daily as
with ops as (
  select
    business_date,
    source,
    count(*)                                                      as order_count,
    count(*) filter (where kot_status = 'COMPLETED')              as completed_count,
    count(*) filter (where kot_status in ('REJECTED','CANCELLED')) as lost_count,
    sum(coalesce(estimated_food_cost, 0))                         as estimated_food_cost,
    sum(coalesce(channel_fees, 0))                                as channel_fees,
    round(avg(prep_seconds)        filter (where prep_seconds is not null))        as avg_prep_seconds,
    round(avg(order_seconds)       filter (where order_seconds is not null))       as avg_order_seconds,
    round(avg(pickup_wait_seconds) filter (where pickup_wait_seconds is not null)) as avg_pickup_wait_seconds,
    round(avg(delivery_seconds)    filter (where delivery_seconds is not null))    as avg_delivery_seconds
  from public.v_analytics_orders
  group by business_date, source
),
rev as (
  select business_date, source, sum(revenue) as revenue, sum(transaction_count) as transaction_count
  from public.v_revenue_by_source
  group by business_date, source
)
select
  coalesce(ops.business_date, rev.business_date) as business_date,
  coalesce(ops.source, rev.source)               as source,
  coalesce(ops.order_count, 0)                   as order_count,
  coalesce(ops.completed_count, 0)               as completed_count,
  coalesce(ops.lost_count, 0)                    as lost_count,
  coalesce(rev.transaction_count, 0)             as revenue_transaction_count,
  coalesce(rev.revenue, 0)                       as revenue,
  coalesce(ops.estimated_food_cost, 0)           as estimated_food_cost,
  coalesce(ops.channel_fees, 0)                  as channel_fees,
  -- Estimated profit = selling price - fees - estimated product cost (PRD 12).
  coalesce(rev.revenue, 0)
    - coalesce(ops.channel_fees, 0)
    - coalesce(ops.estimated_food_cost, 0)       as estimated_profit,
  ops.avg_prep_seconds,
  ops.avg_order_seconds,
  ops.avg_pickup_wait_seconds,
  ops.avg_delivery_seconds
from ops
full outer join rev
  on rev.business_date = ops.business_date and rev.source = ops.source;

-- One-row-per-source rollup for the owner dashboard header.
create view public.v_owner_dashboard as
select
  source,
  sum(order_count)          as order_count,
  sum(revenue)              as revenue,
  sum(estimated_food_cost)  as estimated_food_cost,
  sum(channel_fees)         as channel_fees,
  sum(estimated_profit)     as estimated_profit,
  -- Averages of daily averages are weighted by day, not by order; good enough
  -- for a dashboard headline, and the per-day view is there for detail.
  round(avg(avg_prep_seconds))        as avg_prep_seconds,
  round(avg(avg_order_seconds))       as avg_order_seconds,
  round(avg(avg_pickup_wait_seconds)) as avg_pickup_wait_seconds,
  round(avg(avg_delivery_seconds))    as avg_delivery_seconds
from public.v_kot_metrics_daily
group by source;

-- Integration health, for the Owner/Developer view required by PRD 16, with
-- each capability's honest state attached.
create view public.v_integration_health as
select
  a.provider,
  a.display_name,
  a.is_enabled,
  a.health,
  a.last_healthy_at,
  a.last_error_at,
  a.consecutive_failures,
  a.circuit_open_until,
  (a.credentials_ref is not null) as has_credentials_configured,
  coalesce((
    select jsonb_agg(jsonb_build_object(
             'capability', c.capability,
             'state', c.state,
             'notes', c.notes,
             'reference_url', c.reference_url)
           order by c.capability)
      from public.integration_capabilities c
     where c.provider = a.provider), '[]'::jsonb) as capabilities,
  (select count(*) from public.integration_events e
    where e.provider = a.provider and e.status = 'failed'
      and e.received_at > now() - interval '24 hours') as failed_events_24h,
  (select r.status from public.integration_reconciliation r
    where r.provider = a.provider order by r.ran_at desc limit 1) as last_reconciliation_status
from public.integration_accounts a
where app.has_permission('integrations.view');

grant select on
  public.v_kot_tickets,
  public.v_kot_ticket_items,
  public.v_customer_deliveries,
  public.v_analytics_orders,
  public.v_revenue_by_source,
  public.v_kot_metrics_daily,
  public.v_owner_dashboard,
  public.v_integration_health
to authenticated, service_role;


-- >>> 0090_row_level_security.sql =================================

-- =============================================================================
-- 0090  Row Level Security (PRD 17, PRD 20)
-- =============================================================================
-- Posture:
--   * Reads are governed by RLS on the base tables.
--   * Operational writes (orders, payments, subscriptions, KOT) have NO client
--     write policy at all. They happen only through the SECURITY DEFINER
--     functions in 0011-0014, which validate state, permission and idempotency
--     first. A compromised browser token cannot move a ticket or mint a
--     subscription by writing a column directly.
--   * Catalog and configuration writes are permission-gated policies, because
--     they are ordinary CRUD performed by the Owner.
-- =============================================================================

alter table public.auth_profiles              enable row level security;
alter table public.permissions                enable row level security;
alter table public.role_permissions           enable row level security;
alter table public.employees                  enable row level security;
alter table public.audit_logs                 enable row level security;
alter table public.business_settings          enable row level security;
alter table public.delivery_settings          enable row level security;
alter table public.tax_settings               enable row level security;
alter table public.cost_settings              enable row level security;
alter table public.delivery_windows           enable row level security;
alter table public.categories                 enable row level security;
alter table public.collections                enable row level security;
alter table public.products                   enable row level security;
alter table public.product_images             enable row level security;
alter table public.collection_products        enable row level security;
alter table public.variant_groups             enable row level security;
alter table public.variants                   enable row level security;
alter table public.product_variant_groups     enable row level security;
alter table public.add_ons                    enable row level security;
alter table public.product_add_ons            enable row level security;
alter table public.customers                  enable row level security;
alter table public.customer_addresses         enable row level security;
alter table public.subscription_plans         enable row level security;
alter table public.subscription_plan_windows  enable row level security;
alter table public.subscription_plan_meals    enable row level security;
alter table public.subscriptions              enable row level security;
alter table public.subscription_selected_meals enable row level security;
alter table public.subscription_credit_ledger enable row level security;
alter table public.subscription_deliveries    enable row level security;
alter table public.subscription_delivery_items enable row level security;
alter table public.subscription_pauses        enable row level security;
alter table public.orders                     enable row level security;
alter table public.order_items                enable row level security;
alter table public.order_status_events        enable row level security;
alter table public.kot_tickets                enable row level security;
alter table public.kot_status_events          enable row level security;
alter table public.kot_transitions            enable row level security;
alter table public.kot_daily_counters         enable row level security;
alter table public.payments                   enable row level security;
alter table public.payment_events             enable row level security;
alter table public.refunds                    enable row level security;
alter table public.refund_requests            enable row level security;
alter table public.invoices                   enable row level security;
alter table public.idempotency_keys           enable row level security;
alter table public.coupons                    enable row level security;
