create policy reviews_public_read on public.reviews
  for select using (
    (status = 'published' and deleted_at is null)
    or customer_id = app.current_customer_id()
    or app.has_permission('reviews.moderate'));

create policy reviews_own_insert on public.reviews
  for insert with check (customer_id = app.current_customer_id());

-- A customer may edit or withdraw their own review, but cannot publish it --
-- status changes belong to moderation, enforced by the trigger below.
create policy reviews_own_update on public.reviews
  for update using (customer_id = app.current_customer_id() and deleted_at is null)
  with check (customer_id = app.current_customer_id());

create or replace function app.guard_review_status()
returns trigger
language plpgsql
security definer
set search_path = ''
as $fn$
begin
  if new.status is distinct from old.status
     and not (app.is_direct_connection()
              or app.is_service_role()
              or app.has_permission('reviews.moderate')) then
    raise exception 'only a moderator may change a review''s status'
      using errcode = 'insufficient_privilege';
  end if;

  if new.body is distinct from old.body or new.title is distinct from old.title
     or new.rating is distinct from old.rating then
    new.edited_at := now();
    -- An edited review re-enters moderation rather than staying published.
    if not app.has_permission('reviews.moderate') then
      new.status := 'pending';
    end if;
  end if;

  return new;
end;
$fn$;

create trigger reviews_guard_status
  before update on public.reviews
  for each row execute function app.guard_review_status();

create policy reviews_moderate on public.reviews
  for update using (app.has_permission('reviews.moderate'))
  with check (app.has_permission('reviews.moderate'));

create policy review_moderation_read on public.review_moderation
  for select using (app.has_permission('reviews.moderate'));

-- =============================================================================
-- Notifications and integrations
-- =============================================================================
create policy notification_templates_read on public.notification_templates
  for select using (app.has_permission('notifications.view'));
create policy notification_templates_manage on public.notification_templates
  for all using (app.has_permission('notifications.manage'))
  with check (app.has_permission('notifications.manage'));

create policy notifications_read on public.notifications
  for select using (
    customer_id = app.current_customer_id() or app.has_permission('notifications.view'));

create policy notification_events_read on public.notification_events
  for select using (app.has_permission('notifications.view'));

-- Credential *references* are visible to integration managers only, and the
-- credentials themselves never live in the database at all (PRD 16, PRD 17).
create policy integration_accounts_read on public.integration_accounts
  for select using (app.has_permission('integrations.view'));
create policy integration_accounts_manage on public.integration_accounts
  for all using (app.has_permission('integrations.manage'))
  with check (app.has_permission('integrations.manage'));

create policy integration_capabilities_read on public.integration_capabilities
  for select using (app.is_staff());
create policy integration_capabilities_manage on public.integration_capabilities
  for all using (app.has_permission('integrations.manage'))
  with check (app.has_permission('integrations.manage'));

create policy integration_events_read on public.integration_events
  for select using (app.has_permission('integrations.view'));

create policy integration_reconciliation_read on public.integration_reconciliation
  for select using (app.has_permission('integrations.view'));


-- >>> 0095_realtime.sql ===========================================

-- =============================================================================
-- 0095  Realtime publication (PRD 11)
-- =============================================================================
-- Realtime is the primary mechanism, not a polling fallback. Supabase applies
-- the SELECT policies from 0090 to every change event, so a Kitchen client
-- receives ticket changes and nothing else.
--
-- REPLICA IDENTITY FULL is set on the operational tables so update events
-- carry the previous row too -- clients need the old status to reconcile an
-- out-of-order or duplicated event rather than trusting arrival order.
-- =============================================================================

alter table public.kot_tickets             replica identity full;
alter table public.kot_status_events       replica identity full;
alter table public.subscription_deliveries replica identity full;
alter table public.orders                  replica identity full;
alter table public.integration_accounts    replica identity full;

do $do$
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    create publication supabase_realtime;
  end if;
end
$do$;

-- Adding a table twice raises; ignore the duplicate so the migration is
-- re-runnable against an existing Supabase project.
do $do$
declare
  t text;
begin
  foreach t in array array[
    'kot_tickets',
    'kot_status_events',
    'subscription_deliveries',
    'orders',
    'integration_accounts'
  ] loop
    begin
      execute format('alter publication supabase_realtime add table public.%I', t);
    exception when duplicate_object then
      null;
    end;
  end loop;
end
$do$;


-- >>> 0099_grants.sql =============================================

-- =============================================================================
-- 0099  Explicit privilege grants
-- =============================================================================
-- Supabase grants broad table access to anon/authenticated by default and
-- relies on RLS to filter it. That default is fine for tables, but NOT for
-- functions: several RPCs in this schema are SECURITY DEFINER and must never
-- be callable by a browser token.
--
-- So: table access is granted (RLS is the gate), and function EXECUTE is
-- revoked wholesale and then granted back one function at a time.
-- =============================================================================

grant usage on schema public to anon, authenticated, service_role;

-- Tables: RLS decides what is visible. Operational tables have no write policy
-- at all, so these grants cannot be used to move a ticket or mint an order.
grant select on all tables in schema public to anon, authenticated;
grant insert, update, delete on all tables in schema public to authenticated;
grant all on all tables in schema public to service_role;
grant usage, select on all sequences in schema public to authenticated, service_role;

-- =============================================================================
-- Functions: deny by default
-- =============================================================================
revoke execute on all functions in schema public from public, anon, authenticated;
revoke execute on all functions in schema app    from public, anon, authenticated;

-- Helpers used inside RLS policies must be executable by the roles those
-- policies run as, or every policy evaluation fails.
grant execute on function
  app.current_actor_id(),
  app.current_role(),
  app.is_service_role(),
  app.is_direct_connection(),
  app.has_permission(text),
  app.has_any_permission(text[]),
  app.is_staff(),
  app.is_admin(),
  app.current_customer_id(),
  app.product_is_orderable(uuid, timestamptz),
  app.business_timezone(),
  app.business_now(),
  app.business_date(timestamptz),
  app.setting(text),
  app.setting_numeric(text),
  app.setting_int(text),
  app.setting_bool(text),
  app.setting_text(text),
  app.resolve_delivery_fee(numeric, public.order_source, timestamptz),
  app.resolve_tax_components(text, timestamptz)
to anon, authenticated, service_role;

-- -----------------------------------------------------------------------------
-- Read-only pricing and eligibility. Safe for the storefront: they compute,
-- they never commit.
-- -----------------------------------------------------------------------------
grant execute on function
  public.quote_subscription(uuid, uuid, text)
to anon, authenticated, service_role;

grant execute on function
  public.validate_coupon(text, uuid, numeric, uuid, public.order_source, timestamptz),
  public.subscription_credit_balance(uuid)
to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- Customer actions. Each of these proves the caller owns the subscription it
-- is about to touch (app.assert_subscription_access / assert_customer_access).
-- -----------------------------------------------------------------------------
grant execute on function
  public.begin_subscription_checkout(uuid, uuid, uuid, uuid, public.payment_provider, text, smallint[], jsonb, text, text, date),
  public.schedule_credit_delivery(uuid, date, uuid, jsonb, uuid),
  public.skip_subscription_delivery(uuid, text),
  public.pause_subscription(uuid, date, date, text),
  public.cancel_subscription(uuid, text)
to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- Operational actions. Callable by staff tokens: the transition trigger checks
-- the actor's permission for the specific move being attempted, so an Owner
-- token calling this still cannot accept a ticket.
-- -----------------------------------------------------------------------------
grant execute on function
  public.transition_kot_ticket(uuid, public.kot_status, text, text),
  public.override_prep_eta(uuid, integer)
to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- Service-role only. These mint entitlements, confirm money, or ingest
-- external orders; a browser token must never reach them, whatever RLS says.
-- -----------------------------------------------------------------------------
grant execute on function
  public.confirm_subscription_payment(uuid, text, boolean, text, jsonb),
  public.fail_subscription_payment(uuid, text, text, boolean, jsonb),
  public.generate_subscription_deliveries(uuid, date, date),
  public.release_due_deliveries(timestamptz, integer),
  public.ingest_marketplace_order(public.integration_provider, text, jsonb, jsonb, jsonb, jsonb, text, timestamptz),
  public.sync_marketplace_order_status(public.integration_provider, text, text, text, jsonb),
  public.reconcile_marketplace_orders(public.integration_provider, timestamptz, timestamptz, text[]),
  public.record_integration_failure(public.integration_provider, text),
  public.record_integration_success(public.integration_provider),
  public.record_audit_event(public.audit_action, text, text, jsonb, jsonb, jsonb)
to service_role;

-- New objects created later inherit the same posture.
alter default privileges in schema public
  grant select on tables to anon, authenticated;
alter default privileges in schema public
  grant insert, update, delete on tables to authenticated;
alter default privileges in schema public
  revoke execute on functions from public, anon, authenticated;


